// Lo que FALTÓ de un pedido, desde el chat: `<palabra>[#<color>]=<unidades que LLEGARON>` (`=` adelante = nombre exacto). Cada uno
// tiene que agarrar UN renglón del pedido. Devuelve { llegan: Map(índice → u), problemas }.
function faltoDePedido(items, args, nomDe) {
  const n = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
  const llegan = new Map(), problemas = [];
  for (const a of args) {
    const m = String(a).trim().match(/^(.+?)(?:#(.+?))?=(\d+)$/);
    if (!m) { problemas.push(`"${a}" → se espera <palabra>[#<color>]=<unidades que llegaron>`); continue; }
    const ex = m[1].trim().startsWith('='), q = n(m[1].trim().replace(/^=/, '')), col = m[2] ? n(m[2]) : '';
    const hits = items.map((it, i) => ({ it, i })).filter(({ it }) => it && (ex ? n(nomDe(it)) === q : n(nomDe(it)).includes(q)) && (!col || n(it.variante || it.v || '') === col));
    if (hits.length !== 1) { problemas.push(`"${m[1]}${m[2] ? '#' + m[2] : ''}" → ${hits.length ? 'agarra ' + hits.length + ': ' + hits.slice(0, 6).map(({ it }) => nomDe(it) + (it.variante ? ' · ' + it.variante : '')).join(' | ') : 'ningún renglón del pedido'}`); continue; }
    const u = parseInt(m[3], 10), ped = parseInt(hits[0].it.u) || 0;
    if (u > ped) { problemas.push(`"${m[1]}": dijiste que llegaron ${u} y se pidieron ${ped}`); continue; }
    llegan.set(hits[0].i, u);
  }
  return { llegan, problemas };
}
function precioRedondoAviso(p0, p1) {
  const a = [];
  if (p1 >= 1000 && p1 % 1000 === 0) a.push(`termina redondo (${'$' + p1.toLocaleString('es-AR')}): mejor ${'$' + (p1 - 10).toLocaleString('es-AR')}`);
  const u = p1 > p0 ? umbralRedondoCruzado(p0, p1) : null;
  if (u) a.push(`la suba cruza ${'$' + u.toLocaleString('es-AR')}: quedarse en ${'$' + (u - 10).toLocaleString('es-AR')} salvo que la ganancia extra lo valga (y decirlo en el motivo)`);
  return a.join(' · ');
}

function dayKeyFromISO(iso) {
  const d = new Date(iso);
  const p = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Argentina/Buenos_Aires',
    year: 'numeric', month: '2-digit', day: '2-digit',
  }).formatToParts(d).reduce((o, x) => (o[x.type] = x.value, o), {});
  return `${p.year}_${p.month}_${p.day}`;
}

// ── matching publicación → producto interno POR PALABRAS EN COMÚN ──────────
// Palabras genéricas que no ayudan a distinguir (no cuentan para el match).
const STOP = new Set(['de','con','y','la','el','los','las','para','en','del','al',
  'un','una','x','color','negro','blanco','gris','rojo','azul','verde','celeste',
  'pc','set','the','memoria','luz','led','2','0','1','o','a','tipo','marca',
  'usb','hub','bluetooth','wireless','inalambrico','inalambrica','inalambricos',
  'inalambricas','recargable','flexible','micro','mini','original','premium']);
function toks(s) {
  return [...new Set(norm(s).split(' ').filter((t) => t.length >= 2 && !STOP.has(t)))];
}
function buildProductIndex(products) {
  return (products || [])
    .map((p) => ({ p, toks: toks(p.name) }))
    .filter((x) => x.toks.length);
}
// Devuelve el producto si hay un ganador CLARO (gana al segundo por margen);
// si empatan (ambiguo) o nadie llega a 2 palabras, devuelve null → va a revisión.
function matchProduct(title, index) {
  const tt = new Set(toks(title));
  let best = null, bestScore = 0, second = 0;
  for (const x of index) {
    let s = 0;
    for (const tk of x.toks) if (tt.has(tk)) s++;
    if (s > bestScore) { second = bestScore; bestScore = s; best = x; }
    else if (s > second) { second = s; }
  }
  if (best && bestScore >= 2 && bestScore > second) return best.p;
  // producto de una sola palabra distintiva (ej "Chispero", "B39", "P47")
  if (best && bestScore >= 1 && best.toks.length === 1 && bestScore > second) return best.p;
  return null;
}
// candidatos ordenados (para la lista de revisión de las ambiguas)
function candidatesFor(title, index) {
  const tt = new Set(toks(title));
  return index.map((x) => {
    let s = 0; for (const tk of x.toks) if (tt.has(tk)) s++;
    return { id: x.p.id, name: x.p.name, s };
  }).filter((o) => o.s > 0).sort((a, b) => b.s - a.s).slice(0, 4).map(({ id, name }) => ({ id, name }));
}

// variante de la venta de ML (color/medida) mapeada a una variante del producto
// Qué variante nombra el título de una publicación. Regla: TODAS las palabras de la variante
// tienen que estar en el título, y gana la variante más larga que cumpla. Es la misma regla que
// usa la web (_matchProdVariant), a propósito: si las dos no coinciden, el stock por variante del
// panel y el reparto de la oficina hablarían de aromas distintos.
// Conservadora por diseño: ante la duda no devuelve nada. Un aroma mal adivinado ensucia el stock
// de dos variantes a la vez y no se nota mirando.
function varianteDeTitulo(title, variantes) {
  const tw = new Set(norm(title).split(' ').filter(Boolean));
  let best = '', bestLen = 0;
  for (const v of (variantes || [])) {
    const vw = norm(v).split(' ').filter(Boolean);
    if (!vw.length) continue;
    if (vw.every((w) => tw.has(w)) && vw.length > bestLen) { bestLen = vw.length; best = v; }
  }
  return best;
}
function mlVariant(it, p) {
  const vs = (p && p.variantes) || [];
  if (!vs.length) return '';
  const attrs = it.item?.variation_attributes || [];
  const vals = attrs.map((a) => norm(a.value_name || ''));
  for (const v of vs) if (vals.includes(norm(v))) return v;
  return '';
}
// costo en pesos = "costo real full" de la app × dólar × cantidad.
// La app ya guarda costFullUSD (incluye envío/embalaje y el % devolución en vivo);
