    const yaOk = soloVariante ? (v.variante || '') === newVar
      : (v.prodId || null) === ((p && p.id) || null) && (v.variante || '') === newVar && (p ? !v.sinVincular : !!v.sinVincular);
    if (yaOk) continue;
