// comandos (ficha, techo95, escasez, raros, lupa, escmedir) usaban 2% escrito a mano. Si no se puede leer o está en 0, queda
// el 2% de antes y se dice en el log (con 0 el costo saldría más barato de lo real, que es el lado peligroso).
async function leerMonoPct(db) {
  let v = 0;
  try { v = parseFloat(((await db.get('cyc/monotributo')) || {}).pct) || 0; } catch { v = 0; }
  if (!(v > 0)) { console.log('⚠️ no leí el monotributo vigente (cyc/monotributo/pct): uso 2% como antes'); return 2; }
  return v;
}

// ── EL COSTO DE UNA VENTA CON LA REGLA DE LA WEB (etapa 2 · D4, 29/09/2026, eligió la a) ──
// El resumen de Telegram usaba `v.costo` (el costo de la ficha y el dólar DEL DÍA de esa venta) y
// la web usa el costo congelado del MES (`precios_hist_prod`, si no el de hoy) × el dólar del MES
// (`tc_mes` → cierre → promedio de las ventas del mes terminado → el de hoy). Dos números para la
// misma ganancia. Esto es la copia de `_efectivoCostoVP` / `ventaSinCostoVP` / `gestDeVenta` /
// `monoPct` / `tcForYM` de index.html, paso por paso: si se toca una, se toca la otra.
// Devuelve { costo, sinCosto, gest }: `costo` con los impuestos y, si el neto es estimado, el envío
// de Full adentro (igual que `efectivoCostoVP`); `gest` es el envío de Full para el divisor del %.
async function armarCostoWeb(db, vp) {
  const prods = {}, porNombre = {};
  const nrm = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  for (const p of Object.values((await db.get('cyc/products')) || {})) {
    if (!p || !p.id) continue; prods[p.id] = p; if (p.name) porNombre[nrm(p.name)] = p;
  }
  const hist = (await db.get('cyc/precios_hist_prod')) || {};
  const tcMes = (await db.get('cyc/tc_mes')) || {};
  const snaps = (await db.get('cyc/snapshots')) || {};
  const tcHoy = parseFloat((await db.get('cyc/finanzas/tipo_cambio')) || 0) || 0;
  const mono = (await db.get('cyc/monotributo')) || {};
  const nAR = new Date(Date.now() - 3 * 36e5);
  const curYM = `${nAR.getUTCFullYear()}_${String(nAR.getUTCMonth() + 1).padStart(2, '0')}`;
  const tcVentasCache = {};
  const tcVentasMes = (ym) => {
    if (tcVentasCache[ym] != null) return tcVentasCache[ym];
    let s = 0, n = 0;
    for (const [dk, o] of Object.entries(vp || {})) {
      if (!String(dk).startsWith(ym + '_')) continue;
      for (const v of Object.values(o || {})) { const t = parseFloat(v && v.tcSale); if (t > 0) { s += t; n++; } }
    }
    return (tcVentasCache[ym] = n ? Math.round(s / n * 100) / 100 : 0);
  };
  const tcForYM = (ym) => {
    const m = tcMes[ym];
    if (m != null && m !== '' && !isNaN(parseFloat(m))) return parseFloat(m);
    // Cierre: `tcMes` (el dólar de la ganancia, 2a del 12/10/2026) y si no, el del día del cierre (cierres viejos).
    const sn = snaps[ym]; if (sn && (parseFloat(sn.tcMes) > 0 || sn.tipoCambio)) return parseFloat(sn.tcMes) > 0 ? parseFloat(sn.tcMes) : parseFloat(sn.tipoCambio);
    const t = ym < curYM ? tcVentasMes(ym) : 0;
    return t > 0 ? t : tcHoy;
  };
  const monoVig = () => { const v = parseFloat(mono.pct); return isFinite(v) && v > 0 ? v : 0; };
  const monoPct = (ym) => {
    const h = mono.hist; if (!ym || !h) return monoVig();
    if (h[ym] != null) { const v = parseFloat(h[ym]); if (isFinite(v) && v >= 0) return v; }
    const ks = Object.keys(h).sort();
    if (ks.length && ym > ks[ks.length - 1]) return monoVig();
    const antes = ks.filter((x) => x <= ym);
    if (antes.length) { const v = parseFloat(h[antes[antes.length - 1]]); if (isFinite(v) && v >= 0) return v; }
    if (ks.length) { const v = parseFloat(h[ks[0]]); if (isFinite(v) && v >= 0) return v; }
    return monoVig();
  };
  const prodDe = (v) => (v && v.prodId && prods[v.prodId]) || porNombre[nrm(v && v.prod)] || null;
  const gestDe = (v, p) => {
    if (!p) return 0;
    const q = v.qty || 1, pu = (Number(v.total) || 0) / q;
    if (pu > 0 && pu < UMBRAL_ENVIO_GRATIS) return 0;
    const g = Number(p.netoCalcEnvio) > 0 ? Number(p.netoCalcEnvio) : (Number(p.gestFull) || 0);
    return g > 0 ? g * q : 0;
  };
  return (v, dk) => {
    if (!v || v.cancelada) return { costo: 0, sinCosto: false, gest: 0 };
    const ym = String(dk || '').slice(0, 7);
    const p = prodDe(v);
    const imp = (Number(v.total) || 0) * (mlExtraPct(v.cuenta) + monoPct(ym)) / 100;
    const gest = gestDe(v, p);
    let c;
    const baseUSD = p ? (hist[ym] && hist[ym][p.id] != null ? parseFloat(hist[ym][p.id]) || 0 : (parseFloat(p.costUSD) || 0)) : 0;
    const ship = p ? (parseFloat(p.shipUSD) || 0) : 0;
    if (!p || (!baseUSD && !ship)) c = (Number(v.costo) || 0) + imp;
    else {
      const dev = DEV_LIVE[p.id] || 0;
      c = (baseUSD * (1 + dev / 100) + ship) * tcForYM(ym) * (v.qty || 1) + imp;
    }
    if (v.netoEstimado) c += gest;
    const sinCosto = !(Number(v.costo) > 0) && (!p || (!(baseUSD > 0) && !(ship > 0)));
    return { costo: c, sinCosto, gest };
  };
}

// ── CUANDO ML NO DEJA ESCRIBIR, EL ROBOT TIENE QUE GRITARLO (19/09/2026) ───────────────────
// Salió del peor modo posible: él pidió bajar la Pad 2 a mano, ML contestó 403 con
// `PA_UNAUTHORIZED_RESULT_FROM_POLICIES` / `blocked_by: PolicyAgent`, y al medirlo apareció que
// la aplicación NO puede escribir NADA en ML desde el 17/09 — probado con 4 publicaciones, 3
// cuentas, precio Y garantía: 403 en los 12 intentos. Leer sigue andando perfecto.
//
// LO GRAVE NO FUE EL BLOQUEO, FUE EL SILENCIO. La suba automática venía corriendo todas las
// noches sin lograr cambiar un solo precio, y nadie se enteró en dos días. Cada intento fallido
// se imprimía en una línea del log y ahí moría — el MISMO patrón del `catch {}` vacío, del filtro
// que descarta por omisión y del aviso del dólar que no declaraba su tipo: el dato no se pierde
// con ruido, se pierde en silencio.
//
// Por eso esto vive en UNA función a la que llaman las CINCO que escriben solas en ML (las tres
// que suben, la que baja y la que activa pausadas), y no en cada comando: la regla no puede
// depender de que el próximo que escriba algo se acuerde. Es el mismo motivo que el piso duro.
//
// EL LADO SEGURO ACÁ ES AVISAR DE MÁS. Un mensaje que llega cuando el bloqueo ya se destrabó
// molesta un minuto; no avisar deja al robot haciendo la mímica de trabajar. Por eso alcanza con
// UN intento bloqueado para que salga el aviso.
let BLOQUEO_ML = { frenados: [], ok: 0 };
// LA BASE, PARA LAS FUNCIONES QUE ESCRIBEN PRECIOS (22/09/2026).
// `db` se crea ADENTRO de `main()`, así que `setPriceTo` y `raisePrice` no la tienen y por eso no
// podían dejar el margen al día — que es el motivo real de que `anotarNetoWeb`, escrita el
// 20/08 para eso, nunca se haya enchufado a nada.
// Se apunta acá una sola vez, al arrancar, y SÓLO si no es una corrida de prueba: así una prueba
// no puede escribir nada por este camino aunque alguien se olvide de mirar DRY.
let DB_REF = null;
// ── MODO SÓLO DATOS (09/10/2026, regla suya) ──
// *"no quiero que el robot automático modifique nada ni que dé sugerencias ni nada. SU única función es sacar
// información de la api de ml NADA MÁS. Todo el resto te encargás vos"*. Prendido por defecto (también si la
// config no se puede leer: el lado seguro es no decidir). Lo automático (el ciclo, ml-daily, ml-candidatos) sólo
// LEE de ML y guarda; no mueve precios, no activa, no marca, no descarta, no avisa por Telegram (los avisos quedan
// en `mlapi/cerebroavisos` para Claude). Los comandos que corre Claude (`decido`, `liquidando`, `cajallego`…)
// siguen andando: son las decisiones de Claude. Se apaga con `cyc/mlconfig/soloDatos = 'off'`.
let SOLO_DATOS = true;
// Lo que corre solo (no un comando de Claude): el ciclo sin BILLING_PROBE, ml-daily y ml-candidatos.
const CORRIDA_AUTOMATICA = !process.env.BILLING_PROBE || /^(ml-daily|ml-candidatos)$/.test(String(process.env.GITHUB_WORKFLOW || ''));
function _anotarEscrituraML(res, itemId, que, cuerpo) {
  if (res && res.ok) { BLOQUEO_ML.ok++; return; }
  const t = String(cuerpo || '');
  // Se mira el TEXTO de ML, no sólo el 403: un 403 también sale con el token vencido, y eso se
  // arregla solo en la vuelta siguiente. Lo que hay que avisar es el freno de políticas.
  if (!/PolicyAgent|PA_UNAUTHORIZED_RESULT_FROM_POLICIES/i.test(t)) return;
  if (BLOQUEO_ML.frenados.length < 40) BLOQUEO_ML.frenados.push({ mla: String(itemId), que: String(que || 'escribir') });
}
// Se llama UNA vez al final de la corrida, con la db en la mano. Manda al canal privado de
// precios (sendAlerta), que es donde ya van las decisiones de precio — el canal del resumen del
// día no se toca, regla suya del 13/09.
// Memoria de UN día en `cyc/avisobloqueo`: el ciclo son ~4 corridas diarias y el mismo bloqueo
// mandaría 4 mensajes iguales. Se anota SÓLO si el mensaje salió, igual que el aviso diario: si
// falló el envío y se anotara igual, el bloqueo quedaría callado un día por un aviso que nunca
// llegó.
// Y AVISA TAMBIÉN CUANDO SE DESTRABA, que es la mitad que siempre se olvida: si ayer estaba
// bloqueado y hoy ML aceptó una escritura, sale el mensaje de que ya puede de nuevo. Sin eso él
// se queda creyendo que el robot sigue frenado y toca todo a mano al pedo.
// LA FECHA CON LA QUE SE UBICA UN MOVIMIENTO EN EL TIEMPO.
// MEDIDO el 20/09/2026 con `medirsaldo`, y no se adivina: **los 93 RETIROS de las cuatro cuentas
// vienen SIN `MONEY_RELEASE_DATE`** — es lógico, un retiro no se "libera", es plata que sale— y
// también hay 131 ventas sin esa columna. Fechar todo por ahí **se salteaba los retiros enteros**
// y el disponible no habría bajado nunca: el peor lado para equivocarse.
// Los 93 SÍ traen fecha de movimiento y fecha de acreditación, así que se cae a ésas en orden.
// Si no hay ninguna de las tres, devuelve null y el que llama TIENE que contar esa fila aparte:
// saltearla en silencio es el descarte por omisión anotado cuatro veces en este panel.
// QUÉ REPORTE DE MERCADO PAGO SE USA (24/09/2026). Antes era "el más nuevo" sin mirar qué período
// cubre: si MP había generado el diario de UN día, "A liquidar" salía de ese día solo y el
// disponible no encontraba el punto de partida. Ahora se elige el más nuevo que CUBRE lo que hace
// falta (un largo mínimo y/o arrancar antes de cierta fecha); si ninguno lo cubre, el más nuevo,
// y los frenos de cada comando dicen que no alcanza.
function elegirReporte(lista, { minDias = 0, desdeAntesDe = null } = {}) {
  const ok = (lista || []).filter((x) => x && x.file_name && x.status !== 'pending');
  ok.sort((a, b) => new Date(a.date_created || 0) - new Date(b.date_created || 0));
  const sirve = ok.filter((x) => {
    const b = new Date(x.begin_date || 0).getTime(), e = new Date(x.end_date || 0).getTime();
    if (minDias && !(Number.isFinite(b) && Number.isFinite(e) && (e - b) >= minDias * 864e5)) return false;
    if (desdeAntesDe != null && !(Number.isFinite(b) && b <= desdeAntesDe)) return false;
    return true;
  });
  return sirve[sirve.length - 1] || ok[ok.length - 1] || null;
}

function fechaMov(f, iLib, iSett, iTrans) {
  for (const i of [iLib, iSett, iTrans]) {
    if (i < 0) continue;
    const txt = String(f[i] || '').trim();
    if (!txt) continue;
    const ts = new Date(txt).getTime();
    if (Number.isFinite(ts)) return ts;
  }
  return null;
}

// LEER EL CSV DEL REPORTE DE MERCADO PAGO. Las dos viven acá y no adentro de un comando porque
// las usan VARIOS, y dos copias de la misma cuenta ya se separaron nueve veces en este panel.
//
// SE RESPETAN LAS COMILLAS: un `split(';')` pelado corre las columnas si un texto trae el
// separador adentro, y ahí el neto de una fila se lee de otra columna. Con plata de por medio eso
// no se puede dejar al azar.
function csvPartir(linea, sep) {
  const out = []; let cur = '', dentro = false;
  for (let i = 0; i < linea.length; i++) {
    const c = linea[i];
    if (c === '"') { if (dentro && linea[i + 1] === '"') { cur += '"'; i++; } else dentro = !dentro; }
    else if (c === sep && !dentro) { out.push(cur); cur = ''; }
    else cur += c;
  }
  out.push(cur);
  return out.map((x) => x.trim());
}
// El número puede venir "1234.56" o "1.234,56" según cómo esté configurada la cuenta.
// Devuelve null si no se entiende, y el que la llama TIENE que contar esas filas y avisarlas:
// tratarlas como cero es el error anotado de punta a punta en este panel.
function csvNum(txt) {
  let x = String(txt == null ? '' : txt).replace(/"/g, '').trim();
  if (!x) return null;
  if (x.includes(',') && x.includes('.')) x = x.lastIndexOf(',') > x.lastIndexOf('.')
    ? x.replace(/\./g, '').replace(',', '.') : x.replace(/,/g, '');
  else if (x.includes(',')) x = x.replace(',', '.');
  const v = parseFloat(x);
  return Number.isFinite(v) ? v : null;
}

// PEDIR EL REPORTE DE LIQUIDACIÓN DE MERCADO PAGO. Vive acá y no adentro de cada comando porque
// lo usan DOS (`armarsaldo` y `saldoml`) y dos copias de la misma cuenta ya se separaron nueve
// veces en este panel.
//
// LAS FECHAS: el día de HOY no se puede pedir porque todavía no cerró — medido el 20/09/2026, es
// lo único que separa los pedidos que Mercado Pago acepta de los que rechaza con
// 400 "Error creating Statement". Por eso termina AYER a las 23:59:59 hora de acá.
// Devuelve { ok, txt, desde, hasta }.
async function pedirReporteMP(H, dias) {
  const HUSO = '-03:00';
  const diaLocal = (t) => new Date(t - 3 * 36e5).toISOString().slice(0, 10);
  const desde = diaLocal(Date.now() - Math.max(1, dias) * 864e5) + 'T00:00:00' + HUSO;
  const hasta = diaLocal(Date.now() - 864e5) + 'T23:59:59' + HUSO;
  try {
    const r = await fetch('https://api.mercadopago.com/v1/account/settlement_report', {
      method: 'POST',
      headers: { ...H, 'Content-Type': 'application/json' },
      body: JSON.stringify({ begin_date: desde, end_date: hasta }),
      signal: AbortSignal.timeout(25000),
    });
    const txt = ((await r.text()) || '').replace(/\s+/g, ' ').slice(0, 160);
    return { ok: r.ok, txt: r.ok ? '' : `HTTP ${r.status} · ${txt}`, desde, hasta };
  } catch (e) { return { ok: false, txt: String(e.message || e).slice(0, 90), desde, hasta }; }
}

// RENOVAR EL PERMISO DE UNA CUENTA PARA LEER MERCADO PAGO, CON EL MISMO REINTENTO QUE EL CICLO (etapa 2,
// 20/10/2026). El 02/10 `saldoml` no escribió porque el token de Matías no renovó una vez, y `dispo` sí
// escribió: lo liberado quedó en los dos lados. ML rota el refresh_token en cada uso, así que si otra
// corrida lo renovó un instante antes, el que tenemos en memoria ya no sirve: se relee de la base y se
// reintenta a los 5 s (igual que la vuelta del ciclo). Devuelve { t, motivo }: `t` null si no se pudo, y
// `motivo` dice por qué, SIN el token (el registro es público).
async function _mpTokenReintento(db, label, acc) {
  const limpio = (e) => String((e && e.message) || e).replace(/(access|refresh)_token["':=\s]+[^"',\s}]+/gi, '$1_token=…').slice(0, 140);
  if (!acc || !acc.refresh_token) return { t: null, motivo: 'sin token guardado' };
  let t = null;
  try {
    t = await mlRefresh(ML_CLIENT_ID, ML_CLIENT_SECRET, acc.refresh_token);
  } catch (e1) {
    await new Promise((r) => setTimeout(r, 5000));
    let fresco = {};
    try { fresco = (await db.get('mlapi/tokens/' + label)) || {}; } catch { fresco = {}; }
    try {
      t = await mlRefresh(ML_CLIENT_ID, ML_CLIENT_SECRET, fresco.refresh_token || acc.refresh_token);
      console.log(`   ℹ️ ${label}: la renovación del permiso falló una vez (${limpio(e1)}) y anduvo al reintentar${fresco.refresh_token && fresco.refresh_token !== acc.refresh_token ? ' (otra corrida lo había renovado)' : ''}`);
    } catch (e2) { return { t: null, motivo: limpio(e2) }; }
  }
  try { await db.patch('mlapi/tokens/' + label, { refresh_token: t.refresh_token, updated_ts: Date.now() }); acc.refresh_token = t.refresh_token; }
  catch (e) { console.log(`   ⚠️ ${label}: renové el permiso pero no pude guardarlo (${limpio(e)}): la próxima corrida puede fallar`); }
  return { t, motivo: null };
}

async function avisarBloqueoML(db, DRY) {
  const hoy = new Date(Date.now() - 3 * 3600e3).toISOString().slice(0, 10);
  let marca = '';
  try { marca = String((await db.get('cyc/avisobloqueo')) || ''); } catch { marca = ''; }
  const fren = BLOQUEO_ML.frenados;
  if (!fren.length) {
    if (marca && BLOQUEO_ML.ok > 0) {
      console.log(`🔓 ML volvió a dejar escribir: ${BLOQUEO_ML.ok} cambio(s) aceptado(s) esta vuelta.`);
      const ok = await sendAlerta('🔓 <b>ML volvió a dejarme tocar precios.</b>\n\nEsta vuelta aceptó ' + BLOQUEO_ML.ok + ' cambio(s). El robot vuelve a trabajar solo.', { info: true });
      if (ok && !DRY) { try { await db.set('cyc/avisobloqueo', null); } catch { /* se reintenta mañana */ } }
    }
    return;
  }
  const mlas = [...new Set(fren.map((f) => f.mla))];
  console.log(`\n🚫 ML ME FRENÓ ${fren.length} intento(s) de escritura por políticas (PolicyAgent), en ${mlas.length} publicación(es): ${mlas.slice(0, 12).join(', ')}${mlas.length > 12 ? '…' : ''}`);
  if (marca === hoy) { console.log('   (ya avisé por Telegram hoy, no repito)'); return; }
  const ques = [...new Set(fren.map((f) => f.que))];
  const msg = '🚫 <b>ML no me deja tocar las publicaciones.</b>\n\n'
    + 'Esta vuelta intenté ' + fren.length + ' cambio(s) en ' + mlas.length + ' publicación(es) y ML los rechazó <b>todos</b>, siempre con el mismo motivo: su motor de políticas (<i>PolicyAgent</i>).\n\n'
    + 'Lo que quedó sin hacer: ' + ques.join(' · ') + '.\n'
    + 'Publicaciones: ' + mlas.slice(0, 10).join(', ') + (mlas.length > 10 ? ` y ${mlas.length - 10} más` : '') + '\n\n'
    + '<b>No es un error del robot ni de la cuenta:</b> leer sigue andando bien. Es ML que le cerró la escritura a la aplicación.\n\n'
    + '<b>Qué podés hacer vos:</b> probá cambiarle el precio a una a mano en ML. Si a mano te deja, el freno es sólo contra la aplicación y hay que entrar al panel de desarrolladores de ML con la cuenta que la creó, ver si hay algún aviso y volver a autorizarla.\n\n'
    + '<i>Mientras tanto el robot NO está cambiando ningún precio, aunque el resto siga funcionando.</i>';
  const ok = await sendAlerta(msg);
  if (ok && !DRY) { try { await db.set('cyc/avisobloqueo', hoy); } catch { /* se reintenta en la vuelta siguiente */ } }
}

// ── Subir el precio de TODAS las variantes de una publicación ──────────────
// PELIGRO que esto evita: si a ML le mandás la lista de variantes incompleta,
// BORRA las que faltan (te comés el historial y el stock de esa variante). Por
// eso siempre se manda la lista COMPLETA: las que suben con el precio nuevo y
// las que no, con el precio que ya tenían.
// Después de escribir se vuelve a leer la publicación y se verifica que siga
// teniendo la MISMA cantidad de variantes y los precios pedidos. Si algo no
// coincide, devuelve ok:false para que el que llama frene todo lo demás.
// 'nuevos' = { idVariante: precioNuevo }.  Devuelve {ok, cambios:[{id,from,to}]} o {ok:false, err}.
// REDONDEAR PARA ARRIBA SIN CRUZAR LA BARRERA (23/09/2026, lo agarró la revisión): las funciones
// que suben redondean a la decena de arriba, y un $32.999 pedido a propósito quedaba en $33.000 —
// justo arriba de la barrera, donde ML cobra ~$6.000 de envío en cada venta (regla 2).
// `cruza` (06/10/2026): cuando la 📈 ya midió que pasar la barrera paga CON el envío restado, se deja cruzar.
function redondeoSube(x, cruza) {
  const r = Math.ceil(x / 10) * 10;
  if (cruza) return r;
  return (x < UMBRAL_ENVIO_GRATIS && r >= UMBRAL_ENVIO_GRATIS) ? UMBRAL_ENVIO_GRATIS - 1 : r;
}
// LOS TRES FRENOS DE TODA SUBA, EN UN SOLO LUGAR (revisión max #14, 25/09/2026): el techo de
// $650.000 (regla 3), no cruzar los $33.000 para arriba (regla 2: se frena en $32.999) y no más de
// +25% de una. Vivían en algunas cuentas y no en las funciones que escriben en ML, así que un
// comando a mano (`volver`, `submargen`, `bajopiso`, `preciosgo`) los podía saltear.
// Devuelve { to } con el precio ya ajustado, o { err } si no se puede subir.
const TECHO_DURO = 650000;   // 03/10/2026: subido de $650.000 a $650.000 (regla suya)
const PUBLICAR_MIN_PCT = 35;   // 23/10/2026 (él): "siempre publicar todo arriba del 35% o en 35%" (peor caso); se baja cerca de pagar stock antiguo
const TOPE_CREAR = 550000;   // 23/10/2026 (él): nunca se crea una publicación (Clásica o gemela) más cara que esto
function frenosSuba(from, to, o) {
  from = Number(from) || 0; to = Number(to) || 0;
  if (!(from > 0) || !(to > from)) return { err: 'no-sube' };
  // CRUZAR LA BARRERA SÓLO SI PAGA (06/10/2026, él: "si puede pasar los 33.000, el tema es que a partir
  // de ese monto se le agrega costo de envío: no va a convenir subir de 32.000 a 37.000"). Sólo quien
  // midió la ganancia CON el envío restado puede pedir `cruza`; todo lo demás sigue frenando en $32.999.
  if (!(o && o.cruza) && from < UMBRAL_ENVIO_GRATIS && to >= UMBRAL_ENVIO_GRATIS) {
    to = UMBRAL_ENVIO_GRATIS - 1;
    if (to <= from) return { err: 'no-sube: la barrera de los $33.000 no se cruza' };
  }
  if (to > TECHO_DURO) return { err: `pasa-el-techo-de-${TECHO_DURO}` };
  // El +25% no frena a la 📈 (06/10/2026, él: "que el robot pueda subir tanto como quiera, siempre
  // mirando que el precio sea el que el robot quiera"): su techo ya sale del competidor con Full medido.
  if (!(o && o.libre) && to > from * 1.25) return { err: 'suba-mayor-a-25%' };
  return { to };
}
async function raiseVariations(itemId, nuevos, token) {
  // Mismo freno que `raisePriceTo`: esta función también SUBE precios en ML y se salteaba la
  // lista de "liquidando". Ver la nota en `volver`.
  const _nsRV = await _chequeoNoSubir(itemId);
  if (!_nsRV.ok) return { ok: false, err: _nsRV.err };
  let item;
  try { item = await mlGet('/items/' + itemId + '?attributes=id,price,status,variations', token); }
  catch { return { ok: false, err: 'sin-item' }; }
  if (item.status === 'closed') return { ok: false, err: 'cerrada' };
  const vars = Array.isArray(item.variations) ? item.variations : [];
  if (!vars.length) return { ok: false, err: 'sin-variantes' };
  const antes = vars.length;
  const cambios = [];
  // Las variantes que se pidió subir y NO se subieron (+25%, techo, barrera): se devuelven para que
  // el que llama no diga "subí todas" cuando subió una (revisión max #12).
  const saltadas = [];
  // Lista COMPLETA: toda variante va, cambie o no.
  const payload = vars.map((v) => {
    const n = nuevos[String(v.id)];
    let precio = v.price;
    // P6 de la segunda vuelta (25/09/2026): el precio nuevo sale de medir UNA variante, y otra más
    // barata podía cruzar los $33.000 (regla 2: se frena en $32.999). Acá, que es por donde pasan
    // todas las subas de variantes, cada una que está abajo de la barrera queda como mucho en $32.999.
    if (n && n > v.price) {
      const fr = frenosSuba(v.price, redondeoSube(n));
      if (fr.to > v.price) { precio = fr.to; cambios.push({ id: v.id, from: v.price, to: precio }); }
      else saltadas.push({ id: v.id, price: v.price, pedido: n, why: fr.err || 'no-sube' });
    }
    return { id: v.id, price: precio };
  });
  if (!cambios.length) return { ok: false, err: saltadas.length ? saltadas[0].why : 'no-sube', saltadas };
  try {
    const r = await fetch(ML_API + '/items/' + itemId, {
      method: 'PUT',
      headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
      body: JSON.stringify({ variations: payload }),
    });
    if (!r.ok) {
      // El motivo de ML, no sólo el número: un 403 o un 400 se arreglan distinto y sin el texto
      // no hay forma de saber cuál es.
      let _d = '';
      try { _d = (await r.text() || '').slice(0, 300); } catch { _d = ''; }
      _anotarEscrituraML(r, itemId, 'subir el precio de las variantes', _d);
      return { ok: false, err: 'ML-' + r.status + (_d ? ' · ' + _d : '') };
    }
    _anotarEscrituraML(r, itemId, 'subir el precio de las variantes', '');
  } catch (e) { return { ok: false, err: 'red · ' + String(e.message || e).slice(0, 120) }; }
  // Verificación obligatoria: que no se haya borrado ninguna variante y que los precios sean los pedidos.
  let after = null;
  for (let i = 0; i < 2 && !after; i++) {
    try { after = await mlGet('/items/' + itemId + '?attributes=id,variations', token); }
    catch { await new Promise((res) => setTimeout(res, 3000)); }
  }
  // ML ACEPTÓ el cambio y no se pudo releer (etapa 1, 27/09): devolver "no se hizo" hacía que no se
  // anotara en la memoria del robot y la noche siguiente volviera a subir encima. Se da por hecho
  // y se avisa que falta verificar.
  if (!after) { console.log(`   ⚠️ ${itemId}: ML aceptó el cambio de variantes pero no pude releerlo (queda sin verificar)`); return { ok: true, cambios, saltadas, parcial: saltadas.length > 0, sinVerificar: true }; }
  const vd = Array.isArray(after.variations) ? after.variations : [];
  if (vd.length !== antes) return { ok: false, err: `PELIGRO-variantes-${antes}→${vd.length}` };
  for (const c of cambios) {
    const v = vd.find((x) => String(x.id) === String(c.id));
    if (!v) return { ok: false, err: 'PELIGRO-variante-desaparecida-' + c.id };
    if (Math.round(v.price) !== c.to) return { ok: false, err: `precio-no-quedo-${c.id}-${Math.round(v.price)}` };
  }
  // Recién acá, con los precios verificados contra ML. Ver margenAlDia.
  await margenAlDia(itemId, token, 'subir variantes');
  return { ok: true, cambios, saltadas, parcial: saltadas.length > 0 };
}

// ── Subir una publicación a un precio EXACTO ───────────────────────────────
// Para nivelar grupos hay que llegar a un precio concreto, no multiplicar: el
// multiplicador se aplica sobre lo que ML tenga en ese instante y, si el precio
// cambió desde que se leyó, el resultado se pasa del objetivo.
// Sube o deja igual, nunca baja. Tope de seguridad: no sube más de 25%.
async function raisePriceTo(itemId, objetivo, token, o) {
  const _ns = await _chequeoNoSubir(itemId);
  if (!_ns.ok) return { ok: false, err: _ns.err };
  let item;
  try { item = await mlGet('/items/' + itemId + '?attributes=id,price,status,variations', token); }
  catch { return { ok: false, err: 'sin-item' }; }
  if (item.status === 'closed') return { ok: false, err: 'cerrada' };
  // Revisión final: con variantes un PUT de {price} no sube cada variante (regla 7) y se anotaba una
  // suba que no pasó. Se niega, igual que setPriceTo: para eso está raiseVariations.
  if ((item.variations || []).length) return { ok: false, err: 'tiene variantes: se sube variante por variante (raiseVariations)' };
  if (!item.price) return { ok: false, err: 'sin-precio' };
  // `exacto` (etapa 1, 21/10/2026): el precio que decidió Claude va tal cual ($4.999 no pasa a $5.000); la barrera la sigue frenando frenosSuba.
  const frT = frenosSuba(item.price, (o && o.exacto && Number.isInteger(Number(objetivo))) ? Number(objetivo) : redondeoSube(objetivo, o && o.cruza), o);
  if (frT.err) return { ok: false, err: frT.err };
  const to = frT.to;
  try {
    const r = await fetch(ML_API + '/items/' + itemId, {
      method: 'PUT',
      headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
      body: JSON.stringify({ price: to }),
    });
    // El cuerpo del error, no sólo el número: `setPriceTo` y `raiseVariations` ya lo hacían y
    // acá quedaba la copia vieja, que decía "ML-403" a secas y obligaba a adivinar.
    if (!r.ok) {
      let _d = '';
      try { _d = (await r.text() || '').slice(0, 300); } catch { _d = ''; }
      _anotarEscrituraML(r, itemId, 'subir el precio', _d);
      return { ok: false, err: 'ML-' + r.status + (_d ? ' · ' + _d : '') };
    }
    _anotarEscrituraML(r, itemId, 'subir el precio', '');
    await margenAlDia(itemId, token, 'subir a un precio exacto');
    return { ok: true, from: Math.round(item.price), to };
  } catch { return { ok: false, err: 'red' }; }
}

// ── Envío deducido de las ventas reales, respetando el umbral de $33.000 ──
// El envío NO es una constante del producto: depende de a qué lado de los $33.000 esté el
// precio. Abajo lo paga el comprador (≈$0 para vos); arriba lo paga CYC (≈$6.000).
// Deducir el envío de ventas viejas y aplicarlo al precio de hoy da resultados falsos cuando
// el precio cruzó el umbral: a un Victoria's Secret que vendió barato hace meses le quedaba
// un envío de $275 aplicado a un precio de hoy de $45.300, y su margen figuraba 53% cuando
// en realidad es 31%. Por eso solo se usan las ventas del MISMO lado del umbral.
// Devuelve { envio, usadas, mismoLado } — mismoLado=false avisa que no hubo ventas del lado
// que corresponde y hubo que estimar.
// ── UN PRECIO ESCRITO A LA ARGENTINA ──────────────────────────────────────────────
// "$3.699,99" son tres mil setecientos, no trescientos setenta mil. El punto separa los miles y
// la coma los decimales — salvo cuando el punto trae 1 o 2 dígitos atrás ("3699.99"), que ahí es
// decimal. Sacar todos los símbolos y quedarse con los dígitos, que es lo que hacía el comando de
// bajar precios, multiplica por 100 sin avisar.
function pesosArg(txt) {
  const t = String(txt == null ? '' : txt).replace(/[^\d.,]/g, '');
  if (!t) return 0;
  let ent = t, dec = '';
  const iCom = t.lastIndexOf(',');
  if (iCom >= 0) { ent = t.slice(0, iCom); dec = t.slice(iCom + 1).replace(/\D/g, ''); }
  else {
    const iPun = t.lastIndexOf('.');
    // un punto con 1 o 2 dígitos atrás es decimal; con 3 es separador de miles
    if (iPun >= 0 && t.length - iPun - 1 <= 2) { ent = t.slice(0, iPun); dec = t.slice(iPun + 1); }
  }
  const n = Number(ent.replace(/\D/g, '') + '.' + (dec || '0'));
  return isFinite(n) ? Math.round(n) : 0;
}
const UMBRAL_ENVIO_GRATIS = 33000;
// UNA COMPRA QUE CRUZA LA BARRERA POR CANTIDAD NO MIDE EL ENVÍO DE UNA VENTA SUELTA (revisión max #4,
// 26/09/2026, eligió la a). ML mira el total del PEDIDO (unidades × precio, o el carrito entero con
// el mismo número de venta), no el precio de una unidad: 2 u. a $25.000 son $50.000 y ML le cobra el
// envío a ese pedido. Dividido por unidad parece una venta de abajo de la barrera con un envío caro,
// y pasaba a ser el "peor envío" de toda la publicación: el robot subía +16% un producto sano. Esas
// ventas quedan AFUERA de la cuenta del envío (se usan igual para todo lo demás).
// EL NETO DE UN PRODUCTO VENDIDO SOLO (18/10/2026, regla suya: *"no podés subir el % de un producto por venderse con otro"*).
// En un carrito ML cobra el cargo fijo una vez y el robot reparte el neto por lo que vale cada producto, así que cada uno se
// ve más rentable. Para juzgar un PRODUCTO (línea de tiempo, ficha, techo, pedidos) se usa lo que deja vendido SOLO: el total
// de la venta × la relación neto/precio de sus ventas sueltas al precio unitario más cercano (misma publicación, si no la
// ficha). Sin ventas sueltas para comparar queda el neto del carrito. La venta en sí (y los totales) siguen con el neto real.
// Es la misma cuenta que `netoProductoVP` de index.html: si se toca una, se toca la otra.
// Etapa 2 (20/10/2026): igual que la web en dos cosas que se habían separado: una orden CANCELADA no hace carrito (la otra
// queda como venta suelta) y el precio de referencia es el más parecido en PROPORCIÓN (|log(pu/ref)|), no en pesos.
function prepNetoSolo(vp) {
  const cnt = {}, ref = {};
  for (const [dk0, ents] of Object.entries(vp || {})) {
    for (const v of Object.values(ents || {})) { if (v && !v.cancelada && v.numVenta) { const k = dk0.slice(0, 10) + '|' + (v.cuenta || '') + '|' + v.numVenta; cnt[k] = (cnt[k] || 0) + 1; } }
  }
  const enCarrito = (v, dk) => !!(v && v.numVenta && cnt[String(dk).slice(0, 10) + '|' + (v.cuenta || '') + '|' + v.numVenta] > 1);
  for (const [dk0, ents] of Object.entries(vp || {})) {
    for (const v of Object.values(ents || {})) {
      if (!v || v.cancelada || v.netoEstimado || enCarrito(v, dk0)) continue;
      const tot = Number(v.total) || 0, net = Number(v.neto) || 0, q = Number(v.qty) || 1;
      if (tot <= 0 || net <= 0) continue;
      const it = { pu: tot / q, r: net / tot };
      if (v.mla) (ref['m:' + v.mla] = ref['m:' + v.mla] || []).push(it);
      if (v.prodId) (ref['p:' + v.prodId] = ref['p:' + v.prodId] || []).push(it);
    }
  }
  const neto = (v, dk) => {
    const n = Number(v && v.neto) || 0;
    if (!enCarrito(v, dk)) return n;
    const tot = Number(v.total) || 0, q = Number(v.qty) || 1; if (tot <= 0) return n;
    const lista = ref['m:' + v.mla] || ref['p:' + v.prodId]; if (!lista || !lista.length) return n;
    const pu = tot / q; let mej = null; for (const it of lista) if (!mej || Math.abs(Math.log(it.pu / pu)) < Math.abs(Math.log(mej.pu / pu))) mej = it;
    return Math.round(tot * mej.r);
  };
  return { neto, enCarrito };
}

function compraCruzaBarrera(v, ents) {
  const q = Number(v && v.qty) || 1, unit = (Number(v && v.total) || 0) / q;
  if (!(unit > 0) || unit >= UMBRAL_ENVIO_GRATIS) return false;
  let ped = Number(v.total) || 0;
  if (v.numVenta != null && v.numVenta !== '' && ents) {
    ped = 0;
    for (const w of Object.values(ents)) {
      if (w && !w.cancelada && String(w.numVenta) === String(v.numVenta) && (w.cuenta || '') === (v.cuenta || '')) ped += Number(w.total) || 0;
    }
    ped = Math.max(ped, Number(v.total) || 0);
  }
  return ped >= UMBRAL_ENVIO_GRATIS;
}
// UNA CLÁSICA SIN VENTAS PROPIAS NO MIDE EL ENVÍO CON LAS VENTAS DE UNA PREMIUM (08/10/2026, etapa 1). Si una
// publicación no vendió, el envío se deduce con las ventas de las otras del MISMO producto. Ahí entraban
// las de su hermana Premium, medidas con la comisión CLÁSICA: la diferencia de comisión (~13 puntos, cuotas
// incluidas) aparecía como "envío" — en el Watch S5 ~$65.000 en vez de ~$7.300 — y el rescate subía de más.
// Se sacan las ventas de toda publicación que figure en cyc/mlcuotas (ahí está cada Premium). Si esa lista
// no se pudo leer no se sabe cuál es cuál: no se usan ventas ajenas y va a la tarifa de ML, como una Premium.
function ventasProdClasica(lista, cuotasMap) {
  if (!cuotasMap) return [];
  return (lista || []).filter((v) => !(v && v.mla && cuotasMap[v.mla]));
}
async function envioDeducido(ventas, precioHoy, feeAt, opts = {}) {
  const { modo = 'min' } = opts; // 'min' = mejor caso (para subir) · 'max' = peor caso (para bajar)
  if (!ventas || !ventas.length) return { envio: null, usadas: 0, mismoLado: false };
  const arribaHoy = precioHoy >= UMBRAL_ENVIO_GRATIS;
  const mismas = ventas.filter((v) => (v.tot >= UMBRAL_ENVIO_GRATIS) === arribaHoy);
  // Arriba de la barrera sin ninguna venta de arriba NO hay envío medido: las de abajo dan ~$0 y
  // ese cero a un precio de arriba es falso (F3 de la segunda vuelta, 25/09/2026).
  // 21/10/2026 · etapa 1: y ABAJO de la barrera sin ventas de abajo el envío es CERO (ML no le cobra envío al vendedor abajo de
  // $33.000): antes se usaban las ventas de ARRIBA y un precio de abajo cargaba el envío de arriba.
  if (!mismas.length) return arribaHoy ? { envio: null, usadas: 0, mismoLado: false } : { envio: 0, usadas: 0, mismoLado: true };
  const usar = mismas;
  const vals = [];
  for (const pv of [...new Set(usar.map((v) => Math.round(v.tot)))].slice(-8)) {
    const cv = await feeAt(pv);
    // Si ML no contesta la comisión de algún precio no se mide a medias: el peor caso podría ser
    // justo el que falta. Se devuelve "no medido" y quien llama lo dice.
    if (cv == null) return { envio: null, usadas: 0, mismoLado: false, falloML: true };
    for (const v of usar) if (Math.round(v.tot) === pv) vals.push(Math.max(0, v.tot - v.net - cv));
  }
  if (!vals.length) return { envio: null, usadas: 0, mismoLado: false };
  vals.sort((a, b) => a - b);
  const envio = modo === 'max' ? vals[vals.length - 1] : vals[0];
  return { envio, usadas: vals.length, mismoLado: mismas.length > 0 };
}

// ── ACTIVAR SOLO LAS PAUSADAS QUE TIENEN STOCK EN FULL ────────────────────
// Regla pedida: si una publicación está pausada y tiene mercadería en el depósito de ML (Full),
// que se active sola — pero SOLO si con su precio de hoy llega al piso de ganancia. Una pausada
// no vende nada, así que dejarla dormida con stock pago en Full es plata parada; pero activarla
// abajo del piso es vender perdiendo.
//
// Cuatro frenos, todos a propósito:
//   1. SOLO Full. Si el stock está en el depósito propio no se toca: eso se manda a Full primero.
//      El stock de Full se pide a ML publicación por publicación; si ML no contesta, cuenta 0 y no
//      se activa (nunca se activa "por las dudas").
//   2. SOLO pausadas "limpias". Si ML la pausó por una infracción o está en revisión, tiene un
//      sub_status y no se toca: reactivar eso a la fuerza es buscarse un problema con la cuenta.
//   3. SOLO si llega al piso con el precio que ya tiene. NO se le sube el precio para que entre:
//      subir precio y activar en un mismo movimiento automático es demasiado para dejarlo suelto.
//      Las que no llegan se avisan por Telegram para decidirlas a mano.
//   4. Si la marcaste con noAutoActivar en cyc/mllinks, se respeta y no se toca nunca. Es la forma
//      de pausar algo a mano sin que el robot te lo vuelva a prender.
// ── MARCAR SOLAS LAS CAJAS QUE YA LLEGARON A FULL ─────────────────────────
// Pedido suyo del 19/08/2026. Hasta ahora había que tocar "llegó" a mano en cada caja, y una caja
// que sigue figurando en camino miente dos veces: el panel cuenta como stock algo que ya está en
// ML (y lo cuenta otra vez cuando ML lo informa), y el semáforo se pone rojo sin motivo.
//
// De dónde sale el dato: ML publica las OPERACIONES de cada inventario de Full
// (/stock/fulfillment/operations/search) y ahí aparecen las entradas (inbound / reception) con su
// fecha y su cantidad. Es lo mismo que ya lee el chequeo de la mañana para contar cajas recibidas.
//
// Cómo se reparte cuando hay varias cajas del mismo producto: por ORDEN DE DESPACHO, la más vieja
// primero. Es la única regla que se puede sostener —ML no dice de qué caja vino cada unidad— y
// coincide con cómo salen: la que se despachó antes llega antes.
//
// Una caja se marca recibida SOLO cuando TODOS sus renglones quedaron cubiertos. Si llegó la mitad,
// se deja abierta: media caja recibida sigue siendo una caja en camino.
let _cajas429Espera = 0;   // tope de espera por 429 en una vuelta (ver el reintento adentro)
// `soloAnotar` (09/10/2026, modo SÓLO DATOS): anota lo que ML ya dio de alta de cada caja abierta (`cyc/cajasentrado`)
// pero NO marca ninguna caja, ni rellena faltantes, ni guarda entradas de las marcadas a mano: eso lo decide Claude.
async function cajasQueLlegaron(db, accounts, labels, products, DRY, soloAnotar = false) {
  _cajas429Espera = 0;
  const envios = (await db.get('cyc/envios_full')) || {};
  const links = (await db.get('cyc/mllinks')) || {};
  const pIdx = {}; for (const p of products) pIdx[p.id] = p;
  // Cajas abiertas, de la más vieja a la más nueva.
  const abiertas = [];
  // LAS CAJAS YA MARCADAS TAMBIÉN SE MIRAN (24/09/2026, arreglo 1 del paso 2 de la revisión).
  // Antes quedaban afuera y las entradas de Full que ya se habían llevado volvían a estar libres en
  // la vuelta siguiente: con dos cajas del mismo producto a la misma cuenta, la mercadería de la
  // primera marcaba "llegó completa" también a la segunda, que seguía en el camión. Ahora cada caja
  // marcada DESCUENTA primero lo que ya usó, y recién lo que sobra se reparte entre las abiertas.
  const marcadasAntes = [];
  for (const [id, e] of Object.entries(envios)) {
    if (!e || !e.cuenta || !labels.includes(e.cuenta)) continue;
    const cajas = Array.isArray(e.cajasDet) ? e.cajasDet : [];
    cajas.forEach((c, i) => {
      if (c && c.recibida) {
        const itemsM = (c.items || []).filter((x) => x && x.prodId && x.u > 0);
        if (itemsM.length) marcadasAntes.push({ id, i, e, c, items: itemsM, fecha: e.fecha || '' });
        return;
      }
      if (!c || c.recibida) return;
      const items = (c.items || []).filter((x) => x && x.prodId && x.u > 0);
      if (!items.length) return;   // sin contenido no hay nada que cruzar
      abiertas.push({ id, i, e, c, items, fecha: e.fecha || '' });
    });
  }
  if (!abiertas.length) return { marcadas: [], mirados: 0, msg: null };
  abiertas.sort((a, b) => (a.fecha || '').localeCompare(b.fecha || ''));
  // UNA CAJA DE MÁS DE 45 DÍAS YA NO SE MIRA SOLA (etapa 3, 29/09/2026). Seguía abierta (perdida o con
  // un renglón que no se puede leer) y estiraba la ventana de su producto: en uno que vende mucho se
  // pasaban los 1.000 movimientos y NINGUNA caja nueva de ese producto se podía marcar (se contaba dos
  // veces). Queda abierta y en rojo en la pantalla; se marca o se abre a mano (cajallego / abrircaja).
  const viejas45 = [];   // etapa 5: lo que ya había entrado de éstas se conserva en cyc/cajasentrado (ver abajo)
  {
    const _corte = new Date(Date.now() - 45 * 864e5 - 3 * 36e5).toISOString().slice(0, 10);
    const _viejas = abiertas.filter((ab) => ab.fecha && ab.fecha < _corte);
    viejas45.push(..._viejas);
    if (_viejas.length) {
      console.log(`⚠️ ${_viejas.length} caja(s) abiertas con más de 45 días no se miran solas (se marcan a mano): ${_viejas.slice(0, 8).map((ab) => `${ab.e.cuenta || '?'} ${ab.fecha}${ab.c.track ? ' · ' + ab.c.track : ''}`).join(' · ')}`);
      for (const ab of _viejas) abiertas.splice(abiertas.indexOf(ab), 1);
      if (!abiertas.length) return { marcadas: [], mirados: 0, msg: null };
    }
  }
  // Qué productos hay que mirar, por cuenta, y desde cuándo.
  const porCta = {};
  for (const ab of abiertas) {
    const o = porCta[ab.e.cuenta] = porCta[ab.e.cuenta] || { prods: new Set(), desde: ab.fecha, desdeProd: {} };
    ab.items.forEach((x) => {
      o.prods.add(x.prodId);
      if (ab.fecha && (!o.desdeProd[x.prodId] || ab.fecha < o.desdeProd[x.prodId])) o.desdeProd[x.prodId] = ab.fecha;
    });
    if (ab.fecha && ab.fecha < o.desde) o.desde = ab.fecha;
  }
  // ── LAS MARCADAS A MANO SE LEEN DESDE SU PROPIO DESPACHO (26/09/2026, revisión rev4, decisión 3,
  // opción a) ── Una caja marcada a mano (web o `cajallego`) no guarda QUÉ entradas usó. Se le
  // descontaba "por orden de despacho", pero la ventana arrancaba en la caja ABIERTA más vieja: si
  // sus entradas eran anteriores a eso no estaban en la lista, y el descuento se comía las de la
  // caja siguiente del mismo producto (que quedaba abierta para siempre, o con faltantes falsos).
  // Ahora, para esos productos, la ventana arranca en el despacho de la marcada a mano (sólo las
  // marcadas hace 60 días o menos, para no estirarla sin fin), y en cuanto se ubican sus entradas
  // se le guardan (`recUsadas`) y la vuelta siguiente ya no hace falta leer tan atrás.
  const MANO_DIAS = 60;
  const hoyISO = new Date(Date.now() - 3 * 3600e3).toISOString().slice(0, 10);
  const limMano = new Date(Date.now() - 3 * 3600e3 - MANO_DIAS * 86400e3).toISOString().slice(0, 10);
  const limVentana = new Date(Date.now() - 3 * 3600e3 - 57 * 86400e3).toISOString().slice(0, 10);
  for (const mb of marcadasAntes) {
    if (Array.isArray(mb.c.recUsadas)) continue;
    const recF = String(mb.c.recFecha || '');
    if (!recF || recF < limMano || recF > hoyISO || !mb.fecha) continue;
    // 23/10/2026 (vuelta corta, 194 consultas con 400 "Date range can't be greater than 60 days"): ML no da más de 60 días de
    // movimientos por consulta y la ventana es despacho − 1 día hasta hoy + 1 día. Una marcada a mano DESPACHADA hace más de
    // 57 días estiraba la de todos sus productos y ninguna caja abierta de esos productos se podía leer. Esa ya no protege.
    if (mb.fecha < limVentana) continue;
    const o = porCta[mb.e.cuenta]; if (!o) continue;
    let usa = false;
    for (const it of mb.items) {
      if (!o.prods.has(it.prodId)) continue;   // sin caja abierta de ese producto no hay nada que proteger
      usa = true;
      if (!o.desdeProd[it.prodId] || mb.fecha < o.desdeProd[it.prodId]) o.desdeProd[it.prodId] = mb.fecha;
    }
    if (usa) { mb.aCalcular = true; if (mb.fecha < o.desde) o.desde = mb.fecha; }
  }
  // Entradas a Full por cuenta+producto+variante desde la fecha de la caja más vieja.
  // LAS ENTRADAS SE GUARDAN CON SU FECHA, UNA POR UNA. Sumarlas en un total suelto mezclaba las
  // entradas de una caja VIEJA con las de la caja abierta: la ventana arranca en la caja abierta
  // más vieja, así que una recepción anterior al despacho de esta caja se le acreditaba igual.
  // Con la regla nueva (marcar aunque falte) eso era grave: el 11/09/2026 la prueba iba a marcar
  // una caja de 64 u. despachada el 08/09 dándole entradas del 07/09 — imposibles de ser suyas —
  // y habría borrado 51 unidades REALES del patrimonio. Una entrada anterior al despacho no puede
  // ser de esta caja.
  const recEnt = {};                         // "cuenta|prodId|variante" -> [{ts, left}]
  // Recibido por ML pero TODAVÍA NO VENDIBLE (lo está procesando). No cuenta para marcar la caja
  // —ver el comentario largo más abajo— pero se informa: es la diferencia entre "ML no recibió
  // nada" y "ML lo recibió y lo está dando de alta", que se veían igual (un cero).
  const enProceso = {};
  const kR = (cta, pid, va) => cta + '|' + pid + '|' + (va || '');
  let mirados = 0, opsTotal = 0, fallos = 0;
  const tiposVistos = {};                    // tipo crudo de ML -> cuántas veces vino
  const erroresOp = {};                      // texto del error -> cuántas veces
  const sinLeer = {};                        // renglones cuya consulta a ML falló: NO se pueden dar por faltantes
  const sinLeerProd = {};                    // "cuenta|prodId" cuya publicación ML no contestó: todo el producto queda ciego
  const motivoSL = {};                       // auditoría 14/10: por qué quedó sin leer (sinpub · color · sincolor) → mlapi/cajasciegas, lo lee el informe
  const sinCantidad = [];                    // entradas aceptadas pero sin unidades legibles
  for (const [cta, o] of Object.entries(porCta)) {
    // Etapa 5: sin token esa cuenta NO se leyó. Sus productos quedan "sin leer": si no, abajo se veían
    // como leídos con 0 entradas y se borraba lo ya anotado en cyc/cajasentrado (unidades contadas dos veces).
    const _ciega = () => { for (const pid of o.prods) sinLeerProd[cta + '|' + pid] = true; };
    const acc = accounts[cta]; if (!acc?.refresh_token) { _ciega(); continue; }
    let tok, sid;
    try {
      const t = await mlRefresh(ML_CLIENT_ID, ML_CLIENT_SECRET, acc.refresh_token);
      await db.patch('mlapi/tokens/' + cta, { refresh_token: t.refresh_token, updated_ts: Date.now() });
      tok = t.access_token; sid = acc.seller_id;
    } catch (e) { console.log(`⚠️ cajas de ${cta}: no pude renovar el permiso de ML (${String(e.message || e).slice(0, 80)}) — sus cajas quedan sin leer esta vuelta`); _ciega(); continue; }
    // LA VENTANA ES POR PRODUCTO, NO POR CUENTA (24/09/2026). Arrancaba en la caja abierta más
    // vieja de TODA la cuenta: una sola caja que nunca se marcaba (perdida, o con un renglón que no
    // entra) estiraba la ventana de todos los productos hasta pasar los 1.000 movimientos, y desde
    // ahí ninguna caja nueva de esos productos se podía marcar. Ahora cada producto mira desde su
    // caja abierta más vieja.
    const desdeDe = (pid) => (o.desdeProd && o.desdeProd[pid]) || o.desde || '2020-01-01';
    const isoDesde = (f) => new Date(new Date(f + 'T00:00:00Z').getTime() - 86400e3).toISOString();
    const hastaISO = new Date(Date.now() + 86400e3).toISOString();   // +1 día por si ML anota en otro huso
    // Publicaciones de esos productos en esta cuenta.
    const mlas = Object.entries(links).filter(([m, e2]) =>
      m.startsWith('MLA') && e2 && e2.cuenta === cta && !e2.ignored && o.prods.has(e2.prodId)).map(([m]) => m);
    // UN DEPÓSITO DE FULL ES UN SOLO PRODUCTO-COLOR (24/09/2026, revisión paso 2). Dos publicaciones
    // de la misma cuenta pueden compartir el `inventory_id` (las dos Lupa 90mm), y ahí la entrada
    // ya se dedupa por renglón. Pero si esas dos publicaciones caen en renglones DISTINTOS (otro
    // color por el título, u otra ficha), la MISMA entrada se le acreditaba a los dos y podía
    // marcar dos cajas con una sola mercadería. No se sabe cuál es la buena, así que no se adivina:
    // los dos renglones quedan "sin leer" (la caja se queda abierta, nunca se da por faltante) y
    // se avisa en el log para arreglarlo con `fijarvar`.
    const invRenglon = {};
    const conDeposito = new Set();           // productos con al menos un depósito de Full leído en esta cuenta
    const conDepVar = new Set();             // revisión max (rev4): lo mismo por renglón "cuenta|producto|color"
    for (let k = 0; k < mlas.length; k += 20) {
      let arr;
      const tanda = mlas.slice(k, k + 20);
      // SI ML NO CONTESTA LA PUBLICACIÓN, SUS RENGLONES QUEDAN "SIN LEER" (24/09/2026). Antes era
      // `catch { continue }`: el renglón quedaba en 0 igual que si no hubiera llegado nada, el
      // cuarto freno no se enteraba y la caja podía marcarse con faltantes que no existen.
      const ciegoPub = (m) => { const e2 = links[m]; if (e2 && e2.prodId) sinLeerProd[cta + '|' + e2.prodId] = true; };
      try { arr = await mlGet('/items?ids=' + tanda.join(',') + '&attributes=id,title,status,inventory_id,variations,shipping', tok); }
      catch { tanda.forEach(ciegoPub); fallos++; continue; }
      const contestadas = new Set();
      for (const row of (arr || [])) { const b0 = (row && row.body) || {}; if (row && !(row.code && Number(row.code) !== 200) && b0.id) contestadas.add(b0.id); }
      tanda.filter((m) => !contestadas.has(m)).forEach(ciegoPub);
      for (const row of (arr || [])) {
        const b = row.body || {}; const mla = b.id; if (!mla || !links[mla]) continue;
        if (((b.shipping && b.shipping.logistic_type) || '') !== 'fulfillment') continue;
        const p = pIdx[links[mla].prodId]; if (!p) continue;
        // inventario → variante. Con variantes de ML, cada una tiene su inventario; con una
        // publicación por aroma, la variante sale del título (misma regla que el resto del panel).
        const pares = [];
        const vars = Array.isArray(b.variations) ? b.variations : [];
        if (vars.length) {
          for (const v of vars) {
            if (!v.inventory_id) continue;
            const vals = (v.attribute_combinations || []).map((a) => norm(a.value_name || ''));
            const pv = (p.variantes || []).find((x) => vals.includes(norm(x))) || '';
            pares.push({ inv: v.inventory_id, va: pv });
          }
        } else if (b.inventory_id) {
          // `variant` fijada a mano (probe fijarvar) manda por encima del título: hay fichas donde
          // la variante se llama más largo que el título de ML ("Azul Marino" vs "Azul").
          pares.push({ inv: b.inventory_id, va: links[mla].variant || varianteDeTitulo(b.title || links[mla].title || '', p.variantes) });
        }
        if (pares.length) conDeposito.add(p.id);
        for (const par of pares) conDepVar.add(kR(cta, p.id, par.va));
        for (const par of pares) {
          mirados++;
          const kPar = kR(cta, p.id, par.va);
          const kPrev = invRenglon[par.inv];
          if (kPrev && kPrev !== kPar) {
            sinLeer[kPrev] = true; sinLeer[kPar] = true;
            delete recEnt[kPrev]; delete recEnt[kPar];
            console.log(`⚠️ ${cta} · el depósito ${par.inv} lo comparten dos renglones distintos (${kPrev.split('|').slice(1).join(' · ') || '?'} y ${kPar.split('|').slice(1).join(' · ') || '?'}, ${mla}): no se le acredita a ninguno. Se arregla con fijarvar.`);
            continue;
          }
          invRenglon[par.inv] = kPar;
          try {
            // ML EXIGE LAS DOS FECHAS. Mandando sólo `date_from` contesta
            // 400 "The field date_from and date_to are required" — y como el catch estaba vacío,
            // las 72 consultas fallaban en silencio y el resultado se leía como "ML no informó
            // ninguna entrada". El marcado automático de cajas nunca funcionó por esto.
            // ── HAY QUE PEDIR TODAS LAS PÁGINAS, NO LAS PRIMERAS 50 ──────────────────
            // Esta lista trae TODOS los movimientos del inventario, ventas incluidas, y las
            // entradas son una minoría: en la corrida del 17/09/2026, de 291 movimientos 215 eran
            // `sale_confirmation` y sólo 47 `inbound_reception`. Pidiendo una sola página de 50,
            // en un producto que vende mucho las VENTAS EMPUJAN A LAS ENTRADAS FUERA DE LA LISTA
            // y el renglón lee 0 sin que falle nada — indistinguible de "no llegó".
            //
            // Eso rompió la caja 76236266 de Luciana (05/09): ML dice "511 procesadas, 511 a la
            // venta" y el panel la marcó "llegó · faltaron 218 u.", dando por perdidas 115 Cartas
            // Casino (0 leídas) y 103 Centímetro Blanco (47 de 150) que SÍ estaban. Los dos son
            // justo los que más venden; las sábanas, que casi no venden, leyeron bien. El sesgo
            // del error lo delata: fallaba donde había más ventas tapando las entradas.
            //
            // El corte se detecta SIN confiar en que ML respete `offset`: se cuentan los
            // movimientos nuevos de cada página. Si una página viene llena y no aporta ninguno
            // nuevo, `offset` no está haciendo nada y NO se puede seguir leyendo → el renglón
            // queda marcado como no leído y la caja no se marca. FALTA DE DATO NO ES FALTA DE
            // MERCADERÍA: es la misma regla que ya estaba para el 429.
            // Etapa 3 (20/10/2026): con la ventana estirada por una caja marcada a mano (lee desde SU despacho) lo que más
            // vende pasaba los 1.000 movimientos y quedaba "sin leer". Si la ventana arranca más de 20 días atrás, hasta 3.000.
            const PAG = 50, MAX_PAG = (Date.now() - (new Date(desdeDe(p.id)).getTime() || Date.now()) > 20 * 864e5) ? 60 : 20;   // 1.000 (o 3.000) movimientos
            const opsInv = [], vistosOp = new Set();
            let cortado = false;
            for (let pag = 0; ; pag++) {
              // ── EL 429 SE REINTENTA, ESPACIADO (25/09/2026) ── Medido: 63 de 135 consultas
              // volvían "over_quota" y las 7 cajas abiertas (varias con ML diciendo "procesamiento
              // finalizado") no se marcaban NUNCA — lo correcto sin dato, pero su mercadería se
              // contaba dos veces (en Full y en camino). Se espacia cada consulta y un 429 se
              // reintenta 3 veces con espera creciente; si sigue, queda "sin leer" como siempre.
              let op;
              for (let _r = 0; ; _r++) {
                await new Promise((r) => setTimeout(r, 350));
                try { op = await mlGet(`/stock/fulfillment/operations/search?seller_id=${sid}&inventory_id=${par.inv}&date_from=${isoDesde(desdeDe(p.id))}&date_to=${hastaISO}&limit=${PAG}&offset=${pag * PAG}`, tok); break; }
                catch (e429) {
                  if (_r < 3 && _cajas429Espera < 180000 && /\b429\b|over_quota/.test(String((e429 && e429.message) || e429))) { const _w = [4000, 10000, 20000][_r]; _cajas429Espera += _w; await new Promise((r) => setTimeout(r, _w)); continue; }
                  throw e429;
                }
              }
              const res = (op && op.results) || [];
              let nuevos = 0;
              for (const x of res) {
                const kOp = String(x.id || x.operation_id || '') || JSON.stringify(x).slice(0, 300);
                if (vistosOp.has(kOp)) continue;
                vistosOp.add(kOp); opsInv.push(x); nuevos++;
              }
              if (res.length < PAG) break;           // última página: se leyó todo
              if (!nuevos) { cortado = true; break; }// ML ignora `offset`: no se puede leer más
              if (pag + 1 >= MAX_PAG) { cortado = true; break; }
            }
            if (cortado) { const _kc = kR(cta, p.id, par.va); sinLeer[_kc] = true; if (!motivoSL[_kc]) motivoSL[_kc] = 'tope'; }
            for (const x of opsInv) {
              const tipo = String(x.type || x.operation_type || '').toLowerCase();
              // Guardar TODO lo que contesta ML, aceptado o no. Sin esto, un filtro de tipo que no
              // coincide se ve igual que "ML no informó nada": los dos terminan en cero.
              tiposVistos[tipo || '(sin tipo)'] = (tiposVistos[tipo || '(sin tipo)'] || 0) + 1;
              opsTotal++;
              // LOS AJUSTES QUE SUMAN TAMBIÉN SON ENTRADAS (24/09/2026, decisión suya, opción a).
              // Medido con `enproceso`: ML anotó cajas enteras como `ADJUSTMENT` y no como
              // `INBOUND_RECEPTION` (Filtro agua 70 u. el 11/09, Lupa 90mm 9 u., Protector talón 11
              // y 10). Sin contarlas la caja quedaba "en camino" para siempre y esas unidades se
              // contaban dos veces (en Full y en la caja) hasta que él la marcaba a mano.
              // Sólo los que SUMAN: los que restan son correcciones y se ignoran. Los frenos de
              // siempre valen igual (sólo entradas posteriores al despacho, 3 días mínimos de viaje).
              const esAjuste = tipo.includes('adjust');
              if (!tipo.includes('inbound') && !tipo.includes('reception') && !esAjuste) continue;
              if (esAjuste && !((Number((x.detail || {}).available_quantity) || 0) > 0)) continue;
              // CÓMO MANDA ML LAS UNIDADES (visto el 11/09/2026, volcando el objeto crudo):
              //   detail = {available_quantity, not_available_detail:[{status,quantity}]}  ← lo que
              //            entró EN ESTE movimiento. Es el número que corresponde.
              //   result = {total, available_quantity, ...}  ← el stock que QUEDÓ después.
              // No existe ningún campo `quantity` suelto, que era el que se leía: por eso las
              // entradas se contaban como cero aun cuando ML sí las informaba. Usar `result`
              // sería peor que no arreglarlo: contaría el stock entero en cada movimiento.
              // Las `not_available` (ej. status internal_process) SÍ entraron al depósito, sólo que
              // todavía no están publicables: para saber si la caja llegó cuentan igual.
              // ── SÓLO CUENTA LO QUE ML YA DEJÓ VENDIBLE ────────────────────────────────
              // Hasta el 12/09/2026 acá se sumaban también las `not_available` (lo que ML recibió
              // pero todavía está procesando). El razonamiento era "la pregunta es si la caja
              // llegó" — y para eso estaba bien, pero tenía una consecuencia que no se pensó:
              // MARCAR la caja saca sus unidades de "En camino a Full", y el stock de Full cuenta
              // SÓLO `available_quantity`. O sea que lo recibido-pero-no-procesado no lo contaba
              // NADIE: ni la oficina, ni el camino, ni Full.
              //
              // Pasó de verdad y fue grande: la caja 76236266 de Luciana (05/09, 510 unidades,
              // $338.913) se marcó verde el mismo día que ML la recibió en el depósito, con
              // "Procesamiento en curso" y CERO unidades dadas de alta. Resultado: 510 unidades
              // desaparecidas del patrimonio, y Armar caja pidiendo mandar 50 Centímetros Blancos
              // más cuando ya había 150 ahí adentro.
              //
              // Ahora los DOS lados cuentan el mismo número. Si una unidad nunca llega a estar
              // disponible (rota, descartada), la caja igual se marca por los tres frenos de abajo
              // —10 días + entró la mitad + ML dejó de dar de alta— y sale en ámbar diciendo
              // cuántas faltaron, que es exactamente lo que él quiere mirar.
              const det = x.detail || {};
              let q = Number(det.available_quantity) || 0;
              // Las que entraron pero todavía no se pueden vender se anotan aparte, sólo para
              // decirlo en pantalla: son mercadería que existe y que el panel todavía cuenta como
              // "en camino", que es la verdad.
              let qEsp = 0;
              if (Array.isArray(det.not_available_detail)) for (const d of det.not_available_detail) qEsp += Number(d.quantity) || 0;
              if (qEsp > 0) enProceso[kR(cta, p.id, par.va)] = (enProceso[kR(cta, p.id, par.va)] || 0) + qEsp;
              if (!q && !qEsp) q = Number(x.quantity) || 0;   // respaldo por si ML cambia la forma
              if (q <= 0 && qEsp > 0) continue;                // llegó pero ML no la dejó vendible todavía
              if (q <= 0) { sinCantidad.push(`${tipo} · detail=${JSON.stringify(x.detail)} · result=${JSON.stringify(x.result)}`.slice(0, 400)); continue; }
              const k1 = kR(cta, p.id, par.va);
              // La fecha hace dos cosas: descartar las entradas anteriores al despacho de la caja,
              // y saber si ML TERMINÓ de procesarla (mientras siga dando de alta unidades no se
              // puede decir que faltó nada).
              const ts1 = Date.parse(x.date_created || '') || 0;
              // El id de la entrada es lo que permite anotar en cada caja QUÉ entradas usó, y no
              // prestárselas a otra caja en la vuelta siguiente. De paso, la misma entrada leída
              // dos veces (dos publicaciones de la misma cuenta que comparten el depósito de Full)
              // ya no se suma dos veces al mismo renglón.
              const opId = String(x.id || x.operation_id || '') || (tipo + '|' + (x.date_created || '') + '|' + q);
              const lst = (recEnt[k1] = recEnt[k1] || []);
              if (lst.some((e) => e.op === opId)) continue;
              lst.push({ ts: ts1, left: q, op: opId });
            }
          } catch (eOp) {
            // GUARDAR EL MOTIVO. El catch vacío hacía que 72 consultas fallidas se vieran igual que
            // 72 consultas que no traen nada: en los dos casos el resultado era "ninguna caja
            // quedó cubierta". Es el mismo patrón del `catch {}` que borró un destinatario de
            // Telegram: el dato no se pierde con ruido, se pierde en silencio.
            fallos++;
            // QUÉ RENGLÓN QUEDÓ SIN LEER. El comentario de abajo decía "si no contesta, esa caja se
            // queda abierta" — **y no era cierto**: `fallos` era un contador suelto y nada ataba una
            // consulta fallida a la caja que la necesitaba. Con 50 de 131 consultas rechazadas por
            // el límite de ML (429 over_quota, visto el 14/09/2026), los renglones de esos productos
            // leen 0, que es indistinguible de "no llegó". Si esa caja además pasa los tres frenos,
            // se marca "llegó con faltantes" y se borran del patrimonio unidades que SÍ están.
            // Es el daño exacto del 12/09 (510 unidades) por otro camino.
            // FALTA DE DATO NO ES FALTA DE MERCADERÍA.
            sinLeer[kR(cta, p.id, par.va)] = true;
            // mlGet arma el mensaje como `ML GET <ruta>: <status> <cuerpo>`. La ruta sola mide ~115
            // caracteres, así que recortar por el PRINCIPIO se comía justo el código de error, que
            // es el único dato que sirve. Se corta desde el ": " para quedarse con status + cuerpo.
            const raw = String((eOp && eOp.message) || eOp);
            const corte = raw.indexOf(': ');
            const m = corte > 0 ? raw.slice(corte + 2, corte + 202) : raw.slice(0, 200);
            erroresOp[m] = (erroresOp[m] || 0) + 1;
            /* si no contesta, esa caja se queda abierta: mejor eso que marcarla de más */
          }
        }
      }
    }
    // ── UN PRODUCTO SIN DEPÓSITO DE FULL EN ESTA CUENTA NO SE PUEDE LEER (25/09/2026, f2, a) ──
    // Si ninguna publicación de Full vinculada a esa ficha en esta cuenta dio un depósito (recién
    // publicada y sin vincular, o el alta la dejó sin ficha por empate), sus renglones leían "0
    // recibidas" como si no hubiera llegado nada, y la caja se marcaba con faltantes que borraban
    // esas unidades del patrimonio. No leerlo no es que falte: el producto queda "sin leer" (la
    // caja se queda abierta) y se avisa para vincularlo.
    for (const pid of o.prods) {
      if (conDeposito.has(pid) || sinLeerProd[cta + '|' + pid]) continue;
      sinLeerProd[cta + '|' + pid] = true; motivoSL[cta + '|' + pid] = 'sinpub';
      console.log(`⚠️ ${cta} · ${(pIdx[pid] && pIdx[pid].name) || pid}: no tiene ninguna publicación de Full vinculada en esta cuenta → sus renglones quedan sin leer (la caja no se marca). Vinculá la publicación.`);
    }
    // ── LO MISMO POR COLOR (revisión max (rev4)) ── El freno de arriba es por PRODUCTO: si el
    // producto tiene depósito pero ninguna publicación nombra ESTE color (la 5ª del Centímetro, cuyo
    // título no dice el color), sus entradas caen en el renglón sin color y el del color leía "0
    // recibidas" como dato → la caja se marcaba con faltantes que sí están en Full. Ese renglón queda
    // "sin leer" (la caja se queda abierta) y se avisa para fijar el color.
    const avisadoVar = new Set();
    for (const ab of abiertas) {
      if (ab.e.cuenta !== cta) continue;
      for (const it of ab.items) {
        const va = it.variante || '';
        // Etapa 3 (29/09): un renglón SIN color de un producto con colores no se puede leer (ML anota
        // las entradas en la clave de cada color): queda "sin leer" y se avisa, en vez de marcarse con
        // faltantes falsos o dejar libres las entradas para la caja siguiente.
        if (!va && ((pIdx[it.prodId] && pIdx[it.prodId].variantes) || []).length) {
          const k0 = kR(cta, it.prodId, '');
          if (!sinLeer[k0]) { sinLeer[k0] = true; motivoSL[k0] = 'sincolor'; console.log(`⚠️ ${cta} · ${(pIdx[it.prodId] && pIdx[it.prodId].name) || it.prodId}: la caja lleva unidades SIN color de un producto con colores → ese renglón queda sin leer (la caja no se marca sola).`); }
          continue;
        }
        if (!va || !conDeposito.has(it.prodId)) continue;
        const kV = kR(cta, it.prodId, va);
        if (conDepVar.has(kV) || sinLeer[kV]) continue;
        sinLeer[kV] = true; motivoSL[kV] = 'color';
        if (!avisadoVar.has(kV)) { avisadoVar.add(kV); console.log(`⚠️ ${cta} · ${(pIdx[it.prodId] && pIdx[it.prodId].name) || it.prodId} · ${va}: ninguna publicación de Full de esta cuenta nombra ese color → el renglón queda sin leer (la caja no se marca). Fijá el color con fijarvar.`); }
      }
    }
  }
  // Repartir lo recibido entre las cajas abiertas, la más vieja primero.
  // POR QUÉ SE GUARDA EL DETALLE: el 11/09/2026 él avisó que cajas que habían llegado seguían en
  // naranja horas después. La corrida decía "mirados: 72 · ninguna quedó cubierta" y nada más, o
  // sea que no había forma de saber si ML no informaba nada, si el filtro de tipo no coincidía o
  // si fallaba el cruce de variante. Un cero sin detalle no se puede diagnosticar.
  // UNA CAJA QUE LLEGA INCOMPLETA TAMBIÉN SE MARCA (11/09/2026, pedido suyo: *"cuando el robot vea
  // que la caja llegó que ya la marque. y luego yo me fijo si hubo un problema o no"*).
  // Antes se exigía que TODOS los renglones estuvieran cubiertos, así que una caja a la que le
  // faltaban 2 unidades —rotura, faltante, o que ML no las dio de alta— no se marcaba NUNCA: se
  // quedaba "en camino" para siempre y esas unidades seguían contando en el patrimonio como si
  // existieran. Justo la mercadería que NO coincide era la única que no se resolvía sola.
  // El freno para no marcar de más: se exige que ML haya dejado de procesar la caja
  // (`ESPERA_MS` sin una entrada nueva de ninguno de sus renglones). Marcarla apenas entra la
  // primera unidad sacaría de "en camino" mercadería que ML todavía está dando de alta, y el
  // patrimonio bajaría un día para volver a subir al otro — plata que aparece y desaparece.
  // Y se exige que haya entrado ALGO: una caja perdida entera se queda abierta y en rojo, que es
  // como tiene que verse.
  // TRES FRENOS, NO UNO. Con sólo "ML dejó de recibir hace 3 días" la prueba del 11/09/2026 iba a
  // marcar como llegada una caja despachada 3 días antes con 5 de 65 unidades adentro: las pocas
  // entradas que caían en esa fecha eran la cola de la caja ANTERIOR, no de ésta. Marcar el 8% de
  // una caja no es "llegó con faltantes", es "todavía no llegó" — y habría borrado 60 unidades
  // reales del patrimonio.
  //   · ESPERA_MS  → ML dejó de dar de alta (si sigue procesando, no se puede decir que faltó nada)
  //   · MIN_DIAS   → antes de esto la caja ni siquiera tuvo tiempo de llegar (el viaje son ~8 días,
  //                  `REPO_DIAS_DEMORA` en el panel)
  //   · MIN_PARTE  → tiene que haber entrado la mayor parte. Abajo de eso la caja se queda abierta
  //                  y se pone roja, que es como tiene que verse algo que no llegó.
  // Una caja COMPLETA se marca siempre, sin esperar ninguno de los tres.
  const ESPERA_MS = 3 * 86400e3;
  const MIN_DIAS = 10;
  const MIN_PARTE = 0.5;
  // Una caja COMPLETA tampoco se marca antes de este tiempo de viaje. Si las entradas que la
  // "completan" llegaron antes, son de otra caja: ninguna caja llega a Full en menos de 3 días.
  const MIN_DIAS_COMPLETA = 3;
  for (const arr of Object.values(recEnt)) arr.sort((a, b) => a.ts - b.ts);
  // Primero lo que ya se llevaron las cajas marcadas.
  //  · Si la caja guardó QUÉ entradas usó (`recUsadas`, desde el 24/09/2026), se descuentan ésas.
  //  · Si no las guardó (marcada antes de este arreglo, o a mano desde la web o con `cajallego`),
  //    se descuenta lo que le tocaría por orden de despacho, igual que siempre. Sólo las que se
  //    marcaron dentro de la ventana que se leyó: una marcada antes tiene sus entradas antes, y
  //    ésas ya no están en la lista.
  let descontadas = 0;
  marcadasAntes.sort((a, b) => (a.fecha || '').localeCompare(b.fecha || ''));
  for (const mb of marcadasAntes) {
    const o = porCta[mb.e.cuenta]; if (!o) continue;
    const usadas = Array.isArray(mb.c.recUsadas) ? mb.c.recUsadas : null;
    if (usadas) {
      for (const u of usadas) {
        const e = (recEnt[u.k] || []).find((x) => x.op === u.op);
        if (e) { const t = Math.min(e.left, Number(u.q) || 0); e.left -= t; descontadas += t; }
      }
      continue;
    }
    const recF = String(mb.c.recFecha || '');
    if (!recF) continue;
    const desdeMb = Date.parse((mb.fecha || '1970-01-01') + 'T00:00:00-03:00') || 0;
    // Lo que se va consumiendo se anota, para guardárselo a la caja (decisión 3, arriba).
    const calc = []; let esperado = 0, usado = 0, ciegoMb = false;
    for (const it of mb.items) {
      // La misma regla de antes, ahora con la ventana de ESE producto: una marcada antes de que
      // arranque la ventana tiene sus entradas afuera de la lista.
      const fP = (o.desdeProd && o.desdeProd[it.prodId]) || o.desde || '2020-01-01';
      const desdeVent = new Date(new Date(fP + 'T00:00:00Z').getTime() - 86400e3).toISOString().slice(0, 10);
      if (recF < desdeVent) continue;
      const k1 = kR(mb.e.cuenta, it.prodId, it.variante || '');
      const fx = (mb.c.faltan || []).find((f) => f && f.prodId === it.prodId && (f.variante || '') === (it.variante || ''));
      let queda = fx ? (Number(fx.llego) || 0) : it.u;   // una marcada con faltantes se llevó sólo lo que llegó
      esperado += queda;
      if (sinLeer[k1] || sinLeerProd[mb.e.cuenta + '|' + it.prodId]) ciegoMb = true;
      for (const e of (recEnt[k1] || [])) {
        if (queda <= 0) break;
        if (e.ts < desdeMb || e.left <= 0) continue;
        const t = Math.min(queda, e.left); e.left -= t; queda -= t; descontadas += t;
        usado += t; calc.push({ k: k1, op: e.op, q: t });
      }
    }
    // Se guarda SÓLO si se encontraron TODAS sus unidades y nada quedó sin leer. Si la marcó antes
    // de que ML diera de alta todo, guardar lo encontrado a medias dejaría sus entradas de mañana
    // libres para la caja siguiente: ahí se sigue descontando por orden de despacho, como hoy.
    // Y sólo si TODAS las entradas que usó son anteriores al despacho de la caja SIGUIENTE del mismo
    // producto en la cuenta: una posterior puede ser de esa otra caja, y guardarla la dejaría
    // "prestada" para siempre. Ante la duda no se guarda y queda como antes.
    const sigDe = (pid) => {
      let f = '';
      for (const x of [...abiertas, ...marcadasAntes]) {
        if (x === mb || x.e.cuenta !== mb.e.cuenta || !x.fecha || x.fecha <= (mb.fecha || '')) continue;
        if (x.items.some((y) => y.prodId === pid) && (!f || x.fecha < f)) f = x.fecha;
      }
      return f ? (Date.parse(f + 'T00:00:00-03:00') || 0) : Infinity;
    };
    const tsDe = (u) => { const e = (recEnt[u.k] || []).find((x) => x.op === u.op); return e ? e.ts : Infinity; };
    const antesDeLaSig = calc.every((u) => tsDe(u) < sigDe(u.k.split('|')[1]));
    if (mb.aCalcular && !ciegoMb && esperado > 0 && usado === esperado && antesDeLaSig) mb.calc = calc;
  }
  // ── LO QUE LLEGA TARDE DE UNA CAJA MARCADA CON FALTANTES VUELVE A ESA CAJA (etapa 3, A1, 29/09/2026,
  // eligió la a) ── Una caja que el robot marcó "llegó, faltaron N" no volvía a mirar lo que ML daba de
  // alta después: esas unidades quedaban libres y se las llevaba la caja SIGUIENTE del mismo producto,
  // que podía darse por llegada con su mercadería todavía en el camión. Ahora, antes de repartir entre
  // las abiertas, cada caja marcada por el robot con faltantes (hace 60 días o menos) toma lo libre
  // posterior a su despacho hasta tapar lo que le faltaba, de la más vieja a la más nueva — el mismo
  // orden de siempre. Las marcadas a mano no: ahí el faltante lo confirmó él con ML.
  const rellenos = [];
  for (const mb of marcadasAntes) {
    if (!mb.c.recAuto || !Array.isArray(mb.c.recUsadas) || !Array.isArray(mb.c.faltan) || !mb.c.faltan.length) continue;
    const recF = String(mb.c.recFecha || '');
    if (!recF || recF < limMano) continue;
    if (!porCta[mb.e.cuenta]) continue;
    const desdeMb = Date.parse((mb.fecha || '1970-01-01') + 'T00:00:00-03:00') || 0;
    const extra = [], faltanN = [];
    for (const f of mb.c.faltan) {
      if (!f || !f.prodId) continue;
      const pide = Number(f.pide) || 0;
      const falta = Math.max(0, pide - (Number(f.llego) || 0));
      const k1 = kR(mb.e.cuenta, f.prodId, f.variante || '');
      let q = 0;
      if (falta > 0 && !sinLeer[k1] && !sinLeerProd[mb.e.cuenta + '|' + f.prodId]) {
        let queda = falta;
        for (const e of (recEnt[k1] || [])) {
          if (queda <= 0) break;
          if (e.ts < desdeMb || e.left <= 0) continue;
          const t = Math.min(queda, e.left); e.left -= t; queda -= t; q += t;
          extra.push({ k: k1, op: e.op, q: t });
        }
      }
      const llego = (Number(f.llego) || 0) + q;
      if (llego < pide) faltanN.push({ ...f, llego });
    }
    if (extra.length) rellenos.push({ mb, extra, faltanN: faltanN.length ? faltanN : null });
  }
  // Foto de lo libre ANTES de repartir entre las abiertas: la usa `cajasentrado`, más abajo, que hace
  // el mismo recorrido por su cuenta.
  const libreBase = {};
  for (const [k, arr] of Object.entries(recEnt)) libreBase[k] = arr.map((e) => ({ ts: e.ts, left: e.left }));
  const marcadas = [], detalle = [];
  for (const ab of abiertas) {
    // Sólo cuentan las entradas POSTERIORES al despacho de esta caja. Las de antes son de una caja
    // anterior (ya marcada) y acreditárselas a ésta la daría por llegada sin que haya llegado.
    const desdeCaja = Date.parse((ab.fecha || '1970-01-01') + 'T00:00:00-03:00') || 0;
    const faltan = [];
    const reng = [];
    let algo = false, ultima = 0, hayCiego = false;
    for (const it of ab.items) {
      const k1 = kR(ab.e.cuenta, it.prodId, it.variante || '');
      const ents = (recEnt[k1] || []).filter((e) => e.ts >= desdeCaja && e.left > 0);
      const tiene = ents.reduce((a, e) => a + e.left, 0);
      // `ultima` contesta "¿ML sigue dando de alta ESTA caja?", así que sólo cuentan las entradas
      // que esta caja se lleva de verdad: las primeras `it.u`, de la más vieja a la más nueva —
      // el MISMO recorrido con el que se consumen más abajo. Contando TODAS las que sobran, una
      // entrada de una caja POSTERIOR del mismo producto le reseteaba el reloj a la vieja, y con
      // cajas saliendo cada pocos días la vieja no se quedaba quieta NUNCA.
      let _q = it.u;
      for (const e of ents) { if (_q <= 0) break; _q -= Math.min(_q, e.left); if (e.ts > ultima) ultima = e.ts; }
      const noLeido = !!sinLeer[k1] || !!sinLeerProd[ab.e.cuenta + '|' + it.prodId];
      if (noLeido) hayCiego = true;
      reng.push({ nombre: it.nombre || (pIdx[it.prodId] || {}).name || it.prodId, variante: it.variante || '', pide: it.u, tiene, noLeido });
      if (tiene > 0) algo = true;
      if (tiene >= it.u) continue;
      faltan.push({ prodId: it.prodId, variante: it.variante || '', nombre: it.nombre || (pIdx[it.prodId] || {}).name || it.prodId, pide: it.u, llego: tiene });
    }
    const quieta = ultima > 0 && (Date.now() - ultima) >= ESPERA_MS;
    const pedidas = reng.reduce((a, x) => a + x.pide, 0);
    const entraron = reng.reduce((a, x) => a + Math.min(x.pide, x.tiene), 0);
    const parte = pedidas > 0 ? entraron / pedidas : 0;
    const dias = Math.floor((Date.now() - desdeCaja) / 86400e3);
    const parcial = faltan.length > 0;
    // EL CUARTO FRENO: si alguna consulta a ML falló, esta caja NO se marca. Un renglón que no se
    // pudo leer vale 0 igual que uno que no llegó, y marcar sobre eso borra mercadería real. Una
    // caja completa tampoco se salva del freno: si un renglón quedó ciego, "completa" puede ser
    // falso. Esperar una vuelta no rompe nada; borrar unidades del patrimonio sí.
    const marcar = !hayCiego && dias >= MIN_DIAS_COMPLETA && (!parcial || (algo && quieta && dias >= MIN_DIAS && parte >= MIN_PARTE));
    detalle.push({ cuenta: ab.e.cuenta, fecha: ab.fecha, track: ab.c.track || '', completa: !parcial, marcar, algo, quieta, dias, parte, entraron, pedidas, reng, hayCiego });
    if (!marcar) {
      // ── LA CAJA QUE NO SE MARCA TAMBIÉN APARTA LO SUYO (26/09/2026, revisión rev4, decisión 4, a) ──
      // Antes sólo las cajas que se MARCABAN se llevaban entradas. Una vieja que todavía no se marca
      // (ML sigue procesando otro renglón, un renglón no se pudo leer, no pasó los frenos) dejaba sus
      // entradas libres, y una caja más NUEVA del mismo producto las tomaba como propias y se marcaba
      // "llegó completa" estando en el camión. Ahora cada abierta, de la más vieja a la más nueva,
      // aparta lo que le toca aunque se quede abierta; la nueva sólo ve lo que sobra.
      for (const it of ab.items) {
        const k1 = kR(ab.e.cuenta, it.prodId, it.variante || '');
        let queda = it.u;
        for (const e of (recEnt[k1] || [])) {
          if (queda <= 0) break;
          if (e.ts < desdeCaja || e.left <= 0) continue;
          const t = Math.min(queda, e.left); e.left -= t; queda -= t;
        }
      }
      continue;                                        // ML todavía la está procesando: se deja abierta
    }
    // Consumir SÓLO lo que entró de verdad, de la entrada más vieja a la más nueva. Si se restara
    // lo que pedía el renglón, una caja posterior del mismo producto arrancaría en negativo.
    const usadas = [];
    for (const it of ab.items) {
      const k1 = kR(ab.e.cuenta, it.prodId, it.variante || '');
      let queda = it.u;
      for (const e of (recEnt[k1] || [])) {
        if (queda <= 0) break;
        if (e.ts < desdeCaja || e.left <= 0) continue;
        const t = Math.min(queda, e.left); e.left -= t; queda -= t;
        usadas.push({ k: k1, op: e.op, q: t });
      }
    }
    ab.usadas = usadas;
    ab.faltan = parcial ? faltan : null;
    marcadas.push(ab);
  }
  // ── LO QUE YA ENTRÓ A FULL DE CADA CAJA ABIERTA (24/09/2026, paso 2 de la revisión, opción a) ──
  // Mientras ML da de alta una caja, lo que ya entró se cuenta en Full (lo lee el stock) Y en
  // "en camino" (la caja sigue abierta): el patrimonio sube de mentira y cae de golpe al marcarla.
  // Acá se anota, caja por caja, cuántas unidades de cada renglón ya entraron, con el MISMO
  // recorrido con el que se marcan (entradas posteriores al despacho, de la más vieja a la más
  // nueva, después de descontar lo que ya se llevaron las marcadas). La web las resta de "en camino".
  // Vive APARTE de cajasDet (`cyc/cajasentrado/<envío>__<caja>`) para no reescribir la lista de
  // cajas cada hora encima de lo que él toque en la web. Un renglón que ML no contestó deja la
  // caja con lo anotado ANTES: un "no sé" no puede devolver unidades al camión ni sacarlas.
  try {
    const prevE = (await db.get('cyc/cajasentrado')) || {};
    // Mismo recorrido que el marcado: TODAS las abiertas (marcadas en esta vuelta incluidas) apartan
    // lo suyo en orden, así una caja ciega no le deja sus entradas a la siguiente.
    const libre = libreBase;
    const nuevoE = {};
    for (const ab of abiertas) {
      const key = ab.id + '__' + ab.i;
      const desdeCaja = Date.parse((ab.fecha || '1970-01-01') + 'T00:00:00-03:00') || 0;
      const yaMarcada = !soloAnotar && marcadas.includes(ab);
      let ciego = false; const its = [];
      for (const it of ab.items) {
        const k1 = kR(ab.e.cuenta, it.prodId, it.variante || '');
        if (sinLeer[k1] || sinLeerProd[ab.e.cuenta + '|' + it.prodId]) ciego = true;
        let queda = it.u, q = 0;
        for (const e of (libre[k1] || [])) {
          if (queda <= 0) break;
          if (e.ts < desdeCaja || e.left <= 0) continue;
          const t = Math.min(queda, e.left); e.left -= t; queda -= t; q += t;
        }
        if (q > 0) its.push({ p: it.prodId, v: it.variante || '', q });
      }
      // Revisión final: una caja que esta vuelta QUIERE marcar conserva lo anotado hasta que la marca quede
      // escrita (si la marca no sale, seguía abierta sin su "ya entraron N": contada dos veces). La web no
      // mira este dato de una caja ya marcada, y la vuelta siguiente lo limpia.
      if (yaMarcada) { if (prevE[key]) nuevoE[key] = prevE[key]; continue; }
      if (ciego) { if (prevE[key]) nuevoE[key] = prevE[key]; continue; }
      if (its.length) nuevoE[key] = { track: String(ab.c.track || ''), items: its };
    }
    // Etapa 5: las abiertas de +45 días no se miran, pero lo que ya había entrado de ellas NO se borra
    // (si no, esas unidades volvían a "en camino" estando en Full: contadas dos veces).
    for (const ab of viejas45) { const key = ab.id + '__' + ab.i; if (prevE[key]) nuevoE[key] = prevE[key]; }
    const firma = (o) => JSON.stringify(Object.keys(o).sort().map((k) => [k, o[k]]));
    const nE = Object.values(nuevoE).reduce((a, x) => a + x.items.reduce((b, y) => b + y.q, 0), 0);
    if (firma(nuevoE) !== firma(prevE)) {
      console.log(`📥 Ya entraron a Full de cajas todavía abiertas: ${nE} u. en ${Object.keys(nuevoE).length} caja(s)${DRY ? ' (prueba: no se escribe)' : ''}`);
      if (!DRY) await db.set('cyc/cajasentrado', Object.keys(nuevoE).length ? nuevoE : null);
    }
  } catch (err) { console.log('⚠️ no se pudo anotar lo que ya entró de las cajas abiertas: ' + (err && err.message)); }
  // ── POR QUÉ CADA CAJA ABIERTA NO SE PUEDE LEER (auditoría 14/10/2026) ── Los avisos de arriba (producto sin
  // publicación de Full en esa cuenta, color sin fijar, ML que no contestó) sólo iban a este log de la hora, y el
  // `informe` decía "5 abiertas" sin decir que la del 07/10 de Adriana nunca se iba a poder leer sola. Se guarda la
  // foto en `mlapi/cajasciegas` (fuera de cyc/: la web no la necesita) y la sección 9 del informe la muestra.
  try {
    const ciegas = {};
    for (const ab of abiertas) {
      const rs = [];
      for (const it of ab.items) {
        const k1 = kR(ab.e.cuenta, it.prodId, it.variante || ''), kp = ab.e.cuenta + '|' + it.prodId;
        if (!(sinLeer[k1] || sinLeerProd[kp])) continue;
        rs.push({ n: String((pIdx[it.prodId] && pIdx[it.prodId].name) || it.prodId).slice(0, 50), v: it.variante || '', u: Number(it.u) || 0,
          m: motivoSL[kp] || motivoSL[k1] || 'ml' });
      }
      if (rs.length) ciegas[ab.id + '__' + ab.i] = { cuenta: ab.e.cuenta, track: String(ab.c.track || ''), fecha: String(ab.fecha || ''), r: rs };
    }
    const err1 = Object.entries(erroresOp).sort((x, y) => y[1] - x[1])[0];
    if (!DRY) await db.set('mlapi/cajasciegas', { ts: Date.now(), fallos: Object.values(erroresOp).reduce((a, x) => a + x, 0),
      error: err1 ? String(err1[0]).slice(0, 120) : '', cajas: Object.keys(ciegas).length ? ciegas : null });
  } catch (eCg) { console.log('⚠️ no pude guardar por qué las cajas quedan sin leer: ' + (eCg && eCg.message)); }
  // Guardar las entradas ubicadas de las marcadas a mano (decisión 3). Lista FRESCA, caja buscada por
  // seguimiento + contenido, y sólo si sigue marcada y sin `recUsadas` (si la abrieron o la tocó
  // otro mientras corría la vuelta, no se toca).
  const firmaCajaMano = (c) => JSON.stringify(((c && c.items) || []).filter((x) => x && x.prodId && x.u > 0)
    .map((x) => [String(x.prodId), String(x.variante || ''), Number(x.u) || 0]).sort());
  const aGuardar = marcadasAntes.filter((mb) => mb.calc);
  let manoGuardadas = 0;
  if (aGuardar.length) {
    console.log(`🧾 ${aGuardar.length} caja(s) marcada(s) a mano: ubicadas sus entradas de Full${DRY ? ' (no se guarda)' : ''} → ` + aGuardar.map((mb) => `${mb.e.cuenta} ${mb.fecha}${mb.c.track ? ' (' + mb.c.track + ')' : ''}`).join(' · '));
    // Con SOLO_DATOS también se guarda (etapa 3, 20/10/2026): es un DATO (qué entradas son de una caja que ya marqué yo), no
    // una decisión. Sin esto la vuelta de cada hora leía desde el despacho de la marcada (hasta 60 días) y lo que más vende
    // pasaba el tope de movimientos y quedaba "sin leer".
    if (!DRY) {
      const porEnv = {};
      for (const mb of aGuardar) (porEnv[mb.id] = porEnv[mb.id] || []).push(mb);
      for (const [id, ms] of Object.entries(porEnv)) {
        try {
          const fresca = await db.get('cyc/envios_full/' + id + '/cajasDet');
          if (!Array.isArray(fresca)) continue;
          const arr = fresca.slice(); let cambio = false;
          for (const mb of ms) {
            const tr = String(mb.c.track || ''), fi = firmaCajaMano(mb.c);
            const cand = [];
            arr.forEach((c, j) => { if (c && String(c.track || '') === tr && firmaCajaMano(c) === fi) cand.push(j); });
            const j = cand.includes(mb.i) ? mb.i : (cand.length === 1 ? cand[0] : -1);
            if (j < 0 || !arr[j].recibida || Array.isArray(arr[j].recUsadas) || String(arr[j].recFecha || '') !== String(mb.c.recFecha || '')) continue;
            arr[j] = { ...arr[j], recUsadas: mb.calc, recUsadasCalc: true };
            cambio = true; manoGuardadas++;
          }
          if (cambio) await db.set('cyc/envios_full/' + id + '/cajasDet', arr);
        } catch (eG) { console.log(`⚠️ no pude guardar las entradas de las cajas a mano del envío ${id}: ${(eG && eG.message) || eG}`); }
      }
    }
  }
  // Escribir lo que se les devolvió a las cajas con faltantes (A1, arriba). Lista FRESCA, la caja
  // buscada por seguimiento + contenido, y sólo si sigue marcada por el robot con los MISMOS faltantes.
  let rellenadas = 0;
  if (rellenos.length) {
    console.log(`↩️ ${rellenos.length} caja(s) marcada(s) con faltantes recibieron lo que llegó tarde${DRY ? ' (prueba: no se escribe)' : ''} → `
      + rellenos.map((r) => `${r.mb.e.cuenta} ${r.mb.fecha}${r.mb.c.track ? ' (' + r.mb.c.track + ')' : ''}: +${r.extra.reduce((a, x) => a + x.q, 0)} u.${r.faltanN ? '' : ' · ya quedó completa'}`).join(' · '));
    if (!DRY && !soloAnotar) {
      const porEnvR = {};
      for (const r of rellenos) (porEnvR[r.mb.id] = porEnvR[r.mb.id] || []).push(r);
      for (const [id, rs] of Object.entries(porEnvR)) {
        try {
          const fresca = await db.get('cyc/envios_full/' + id + '/cajasDet');
          if (!Array.isArray(fresca)) continue;
          const arr = fresca.slice(); let cambio = false;
          for (const r of rs) {
            const mb = r.mb, tr = String(mb.c.track || ''), fi = firmaCajaMano(mb.c);
            const cand = [];
            arr.forEach((c, j) => { if (c && String(c.track || '') === tr && firmaCajaMano(c) === fi) cand.push(j); });
            const j = cand.includes(mb.i) ? mb.i : (cand.length === 1 ? cand[0] : -1);
            if (j < 0 || !arr[j].recibida || !arr[j].recAuto || !Array.isArray(arr[j].recUsadas)
              || String(arr[j].recFecha || '') !== String(mb.c.recFecha || '')
              || JSON.stringify(arr[j].faltan || null) !== JSON.stringify(mb.c.faltan || null)) {
              console.log(`ℹ️ la caja ${tr || '(sin seguimiento)'} del envío ${id} cambió mientras corría la vuelta: no se le devuelve nada`);
              continue;
            }
            arr[j] = { ...arr[j], faltan: r.faltanN, recUsadas: [...arr[j].recUsadas, ...r.extra] };
            cambio = true; rellenadas++;
          }
          if (cambio) await db.set('cyc/envios_full/' + id + '/cajasDet', arr);
        } catch (eR) { console.log(`⚠️ no pude devolverle lo que llegó tarde a las cajas del envío ${id}: ${(eR && eR.message) || eR}`); }
      }
    }
  }
  if (!marcadas.length) return { marcadas: [], mirados, msg: null, detalle, manoGuardadas, rellenadas, tiposVistos, opsTotal, fallos, erroresOp, sinCantidad, recEnt, enProceso, abiertas: abiertas.length, descontadas };
  // Las que de verdad quedaron escritas (en prueba, todas): de ésas sale el mensaje.
  const hechas = DRY ? marcadas.slice() : [];
  // LAS COMPLETAS SE MARCAN SOLAS TAMBIÉN EN SÓLO DATOS (24/10/2026, él con la caja 79567049 de Matías, 93/93 procesada en ML y 8 días
  // "no llegó" en el panel: "ya llegó hace un tiempo, ¿no tenés datos suficientes para darte cuenta? ¿o por qué no se marcó?"). Una caja
  // en la que entró TODO lo que se mandó no tiene nada que decidir: es mecánico, como alinear las gemelas. Las que tienen faltantes siguen
  // quedando para Claude (`cajallego` con el faltante confirmado).
  let escribirCajas = !soloAnotar;
  if (soloAnotar) {
    const parciales = marcadas.filter((m) => (m.faltan || []).length);
    if (parciales.length) console.log(`📦 SÓLO DATOS: ${parciales.length} caja(s) que según ML ya entraron CON FALTANTES — NO las marco, las marca Claude:`);
    for (const m of parciales) {
      const uF = (m.faltan || []).reduce((a, x) => a + (x.pide - x.llego), 0);
      console.log(`   · ${m.e.cuenta} · caja del ${m.fecha}${m.c.track ? ' (' + m.c.track + ')' : ''} · ${m.items.reduce((a, x) => a + x.u, 0)} u. · faltarían ${uF} u.`);
    }
    for (let i = marcadas.length - 1; i >= 0; i--) if ((marcadas[i].faltan || []).length) marcadas.splice(i, 1);
    if (marcadas.length) console.log(`📦 ${marcadas.length} caja(s) entraron COMPLETAS según ML: se marcan solas (regla suya del 24/10)`);
    escribirCajas = marcadas.length > 0;
  }
  if (!DRY && escribirCajas) {
    // Se escribe la lista COMPLETA de cajas del envío: cajasDet es un array y un patch parcial la
    // rompería, igual que pasa con las variantes de ML.
    // ── SE RELEE JUSTO ANTES DE ESCRIBIR (revisión max (rev4)) ── La lista salía de la foto leída
    // al empezar, minutos antes (350 ms por consulta + esperas de 429). Si en ese rato él deshacía,
    // marcaba, cambiaba el seguimiento o agregaba una caja del mismo envío en la web, el robot se lo
    // pisaba: una caja deshecha volvía a "en camino" con sus unidades ya de vuelta en la oficina
    // (contadas dos veces). Ahora cada caja se busca en la lista FRESCA por seguimiento + contenido
    // (no por posición) y se marca sólo ésa, sobre la lista fresca. Si ya no está, cambió, o ya la
    // marcaron, no se toca y se dice en el log.
    const firmaCajaRel = (c) => JSON.stringify(((c && c.items) || []).filter((x) => x && x.prodId && x.u > 0)
      .map((x) => [String(x.prodId), String(x.variante || ''), Number(x.u) || 0]).sort());
    const porEnvio = {};
    for (const m of marcadas) (porEnvio[m.id] = porEnvio[m.id] || []).push(m);
    const hoy = dayKeyFromISO(new Date().toISOString()).replace(/_/g, '-');
    for (const [id, ms] of Object.entries(porEnvio)) {
      let fresca;
      try { fresca = await db.get('cyc/envios_full/' + id + '/cajasDet'); }
      catch (eR) { console.log(`⚠️ no pude releer las cajas del envío ${id}: no se marca ninguna esta vuelta (${(eR && eR.message) || eR})`); continue; }
      if (!Array.isArray(fresca)) { console.log(`⚠️ las cajas del envío ${id} ya no están (o cambió su forma): no se toca nada`); continue; }
      const arr = fresca.slice();
      const tomadas = new Set(), idxs = [];
      for (const m of ms) {
        const tr = String(m.c.track || ''), fi = firmaCajaRel(m.c);
        const cand = [];
        arr.forEach((c, j) => { if (c && !tomadas.has(j) && String(c.track || '') === tr && firmaCajaRel(c) === fi) cand.push(j); });
        const j = cand.includes(m.i) ? m.i : (cand.length === 1 ? cand[0] : -1);
        const nom = `la caja ${m.i + 1} del envío ${id}${tr ? ' (' + tr + ')' : ''}`;
        if (j < 0) { console.log(`⚠️ ${nom}: ${cand.length ? 'hay varias iguales' : 'ya no está o la cambiaron en la web'} mientras corría la vuelta → no se marca`); continue; }
        if (arr[j].recibida) { console.log(`ℹ️ ${nom}: ya estaba marcada (a mano, mientras corría la vuelta) → no se toca`); continue; }
        tomadas.add(j);
        arr[j] = { ...arr[j], recibida: true, recFecha: hoy, recAuto: true, faltan: m.faltan || null, recUsadas: m.usadas || [] };
        idxs.push(j); hechas.push(m);
      }
      if (!idxs.length) continue;
      try { await db.set('cyc/envios_full/' + id + '/cajasDet', arr); }
      catch (eW) { console.log(`⚠️ no pude marcar las cajas del envío ${id}: ${(eW && eW.message) || eW} — quedan abiertas`); for (const m of ms) { const k = hechas.indexOf(m); if (k >= 0) hechas.splice(k, 1); } continue; }
      // Releído: que la escritura no dé error no prueba que haya quedado.
      const rel = (await db.get('cyc/envios_full/' + id + '/cajasDet')) || [];
      const arrRel = Array.isArray(rel) ? rel : Object.values(rel);
      for (const i of idxs) if (!arrRel[i] || !arrRel[i].recibida) console.log(`⚠️ la caja ${i + 1} del envío ${id} NO quedó marcada`);
    }
  }
  const det = hechas.map((m) => {
    const uF = (m.faltan || []).reduce((a, x) => a + (x.pide - x.llego), 0);
    return `· ${m.e.cuenta} · caja del ${m.fecha}${m.c.track ? ' (' + m.c.track + ')' : ''} · ${m.items.reduce((a, x) => a + x.u, 0)} u.`
      + (uF ? ` — ⚠️ faltaron ${uF} u.` : '');
  }).join('\n');
  // Cuántas de las escritas se marcaron CON faltantes: sólo ésas se avisan por Telegram (rev4).
  const conFaltantes = hechas.filter((m) => (m.faltan || []).length).length;
  return {
    marcadas, hechas, conFaltantes, rellenadas, mirados, detalle, tiposVistos, opsTotal, fallos, erroresOp, sinCantidad, recEnt, enProceso, abiertas: abiertas.length, descontadas,
    msg: hechas.length ? `📦 <b>${hechas.length} caja(s) llegaron a Full</b>\n${det}\n\nYa cuentan como stock de la cuenta.` : null,
  };
}

// ── LA CAJA DE COMPRA DE CADA PUBLICACIÓN, GUARDADA PARA QUE LA VEA LA PANTALLA ───────
// Qué contesta, y no lo contesta ningún otro número del panel: en una publicación de CATÁLOGO
// ML muestra UN SOLO botón de comprar y se lo lleva un vendedor. Si la caja la tiene otro, la
// publicación está activa, con stock y con buen margen… y no vende, porque el comprador ni la ve.
// Eso no se deduce del precio, ni del margen, ni de las ventas: hay que preguntárselo a ML.
//
// Por qué se guarda en vez de pedirlo cuando se mira la pantalla: la web no tiene el token de ML
// (ni puede tenerlo). El mismo camino que ya usan las visitas — el robot pregunta y deja el dato
// en cyc/mllinks/<MLA>, la pantalla lo lee de ahí.
//
// Los tres estados que devuelve ML (`/items/<MLA>/price_to_win`) se guardan normalizados, para
// que la pantalla no tenga que conocer los nombres de ML:
//   winning → la caja es nuestra · sharing → la compartimos · losing → la tiene otro
// Y dos más nuestros: `nocat` (no es de catálogo, no hay caja que pelear) y `sincaja` (es de
// catálogo pero ML no informa ganador).
//
// Si ML no contesta para una publicación NO se escribe nada: queda el dato de la vuelta anterior.
// Mejor un dato de hace una hora que un "no sé" que borre lo que sabíamos.
// 6.D4 · cada cuánto y cuántas por vuelta se le pide a ML el precio sugerido de las publicaciones sin catálogo.
const SUG_CADA_H = 20, SUG_MAX_VUELTA = 40;
// Lee la respuesta de `/suggestions/items/<MLA>/details` sin adivinar: el precio sugerido y el más barato parecido, si vienen
// como número (suelto o en `.amount`). Lo que no viene es null.
function leerSugerenciaML(sg) {
  const num = (x) => { const v = x && typeof x === 'object' ? Number(x.amount ?? x.price ?? x.value) : Number(x); return Number.isFinite(v) && v > 0 ? Math.round(v) : null; };
  if (!sg || typeof sg !== 'object') return { sug: null, min: null };
  return { sug: num(sg.suggested_price), min: num(sg.lowest_price) };
}
// 6.D6 · LAS ETIQUETAS DE ML QUE SON UN PROBLEMA de la publicación (la foto, la ficha técnica, una moderación). Las "buenas" o
// neutras (good_quality_thumbnail, immediate_payment, cart_eligible…) no salen. Devuelve la lista en castellano; con salud (0-1)
// menor a 0,7 también avisa. Las etiquetas que no se conocen y suenan a problema salen crudas (no se adivina qué son).
const ETQ_PROBLEMA = { poor_quality_thumbnail: 'foto principal de mala calidad', poor_quality_picture: 'fotos de mala calidad', unknown_quality_picture: 'ML no pudo evaluar la foto',
  incomplete_technical_specs: 'ficha técnica incompleta', incomplete_compatibilities: 'compatibilidades incompletas', moderation_penalty: 'penalizada por moderación',
  under_infractions: 'con infracciones', catalog_forewarning: 'aviso de catálogo', lost_me1_by_user: 'perdió el envío por usuario', dragged_bids_and_visits: 'visitas arrastradas de otra' };
function etqProblemas(etq, salud) {
  const out = [];
  for (const t of String(etq || '').split(',').map((x) => x.trim()).filter(Boolean)) {
    if (ETQ_PROBLEMA[t]) out.push(ETQ_PROBLEMA[t]);
    else if (/poor|bad_|low_quality|incomplete|penalt|infraction|forewarning|warning|missing|without_/i.test(t)) out.push(t);
  }
  if (salud != null && Number(salud) < 0.7) out.push(`salud de la publicación ${Math.round(Number(salud) * 100)}%`);
  return out;
}
// 6.D2 · ¿la caja se pierde por las cuotas y no por el precio? Pierde o comparte, el que gana NO está más barato que nosotros
// (está a nuestro precio o más caro, 2% de margen) y ML dice que nos faltan cuotas sin interés (`free_installments` que no
// está `boosted`). Sin el precio del que gana o sin `boosts`, no se opina (devuelve false).
function cajaPerdidaPorCuotas(st, precio, ganP, boosts) {
  if (st !== 'losing' && st !== 'sharing') return false;
  if (!(precio > 0) || !(ganP > 0) || !Array.isArray(boosts)) return false;
  const cuo = boosts.find((x) => /^free_installments:/.test(x));
  if (!cuo || /:boosted$/.test(cuo)) return false;
  return ganP >= precio * 0.98;
}
// 🥊 MANTENER LA CAJA HASTA QUE SE VENDA (26/10/2026, él con la waflera: "quiero que vendamos la waflera, estamos ganando? podés
// mantenerla en ganando siempre hasta que se venda? sin bajar muchísimo"). `cyc/ganacaja/<MLA>` = {piso, m, desde, por}: lo carga
// `ganarcaja:<MLA>=<piso>|motivo;go` SÓLO con su pedido (es su autorización para ESA publicación: pasa por encima de 🔒/🧊 y de "sin
// línea de techo", nunca del piso que él aceptó ni del 35% del peor caso). Cada hora, después de leer la caja: si la perdemos o la
// compartimos y ML dice el precio para ganarla, se baja a ese precio (terminado en 90, sin pasarlo) mientras no quede abajo del piso;
// como mucho 15% por hora (escalera). Ganándola no se toca. Con stock 0 no hace nada (se vendió). Se relee de ML.
async function mantenerCaja(db, accounts, DRY) {
  const out = { mirados: 0, bajadas: [], no: [] };
  const G = (await db.get('cyc/ganacaja')) || {}; const mlas = Object.keys(G).filter((m) => G[m] && Number(G[m].piso) > 0);
  if (!mlas.length) return out;
  const links = (await db.get('cyc/mllinks')) || {}; const np = (await db.get('cyc/netopub')) || {};
  const tc = parseFloat(await db.get('cyc/finanzas/tipo_cambio')) || 0;
  const prods = Object.values((await db.get('cyc/products')) || {});
  const toks = {};
  for (const mla of mlas) {
    const e = links[mla] || {}, g = G[mla], piso = Number(g.piso);
    out.mirados++;
    const nom = String(e.title || mla).slice(0, 40);
    if (!e.cuenta) { out.no.push(`${nom}: sin cuenta`); continue; }
    const st = e.caja; const ptw = Number(e.cajaPtw) || 0;
    if (st === 'winning') { out.no.push(`${nom}: ganando la caja, no se toca`); continue; }
    if (!['losing', 'sharing'].includes(st) || !(ptw > 0)) { out.no.push(`${nom}: caja "${st || '?'}" sin precio para ganarla`); continue; }
    if (!toks[e.cuenta]) { const acc = accounts[e.cuenta]; if (!acc?.refresh_token) { out.no.push(`${nom}: sin permiso de ${e.cuenta}`); continue; }
      try { const t = await mlRefresh(ML_CLIENT_ID, ML_CLIENT_SECRET, acc.refresh_token); await db.patch('mlapi/tokens/' + e.cuenta, { refresh_token: t.refresh_token, updated_ts: Date.now() }); toks[e.cuenta] = t.access_token; } catch { out.no.push(`${nom}: no pude renovar el permiso`); continue; } }
    let it; try { it = await mlGet('/items/' + mla + '?attributes=id,price,status,available_quantity', toks[e.cuenta]); } catch { out.no.push(`${nom}: ML no contestó`); continue; }
    if (it.status !== 'active' || !(Number(it.available_quantity) > 0)) { out.no.push(`${nom}: ${it.status !== 'active' ? 'no está activa' : 'sin stock (¿se vendió?)'}`); continue; }
    const p0 = Number(it.price) || 0;
    let to = Math.floor((ptw - 90) / 100) * 100 + 90; if (to > ptw) to -= 100;
    to = Math.max(to, Math.ceil(p0 * 0.85 / 10) * 10);   // escalera: como mucho 15% por hora
    if (to < piso) { out.no.push(`${nom}: para ganar la caja pide ${money(ptw)}, abajo del piso que aceptó (${money(piso)}): se queda en ${money(p0)}`); continue; }
    if (!(to < p0)) { out.no.push(`${nom}: ya está en ${money(p0)}, el precio para ganar es ${money(ptw)}`); continue; }
    // El % en que queda (para el piso duro de setPriceTo): neto a ese precio con la misma proporción que el de hoy, menos impuestos y costo.
    const n0 = np[mla] && Number(np[mla].neto) > 0 && Number(np[mla].precio) > 0 ? Number(np[mla].neto) / Number(np[mla].precio) : 0.8;
    const pr = prods.find((x) => x && x.id === e.prodId); const cu = pr && tc > 0 ? costoPesos(pr, 1, tc).costo : 0;
    const imp = mlExtraPct(e.cuenta) / 100 + 0.04;
    const mg = cu > 0 ? ((to * n0 - to * imp - cu) / to) * 100 : null;
    if (mg == null || mg < 35) { out.no.push(`${nom}: a ${money(to)} quedaría en ${mg == null ? '?' : mg.toFixed(0) + '%'} (abajo del 35%): no bajo`); continue; }
    if (DRY) { out.bajadas.push({ mla, nom, de: p0, a: to, mg, dry: true }); continue; }
    const r = await setPriceTo(mla, null, to, toks[e.cuenta], { margen: mg, exacto: true, ganacaja: true, autorizado: `él pidió mantener la caja hasta que se venda (${g.m || ''})` });
    if (!r.ok) { out.no.push(`${nom}: no pude bajar a ${money(to)} (${r.err})`); continue; }
    let rel = 0; try { rel = Number((await mlGet('/items/' + mla + '?attributes=id,price', toks[e.cuenta])).price) || 0; } catch { rel = 0; }
    out.bajadas.push({ mla, nom, de: p0, a: to, rel, mg });
    try { await db.patch('cyc/ganacaja/' + mla, { ult: { ts: Date.now(), de: p0, a: to, ptw } }); } catch { /* el log ya lo dice */ }
    try { await db.set('cyc/claudecambios/' + Date.now() + '_' + mla, { mla, de: p0, a: to, ts: Date.now(), motivo: 'mantener la caja (lo pidió él)' }); } catch { /* */ }
  }
  return out;
}
async function cajaDeCompraML(db, accounts, labels, DRY, soloCta) {
  const links = (await db.get('cyc/mllinks')) || {};
  const upd = {};
  const res = { winning: 0, sharing: 0, losing: 0, nocat: 0, sincaja: 0, mirados: 0, filas: [], cats: new Set(), catsNuevas: 0, catsFaltan: 0, fotos: 0, porCuotas: 0, sug: 0, sugSin: 0 };
  let tokUno = null;
  const _sugPend = [];   // 6.D4: las sin catálogo a las que hay que pedirles el precio sugerido de ML en esta vuelta
  for (const label of labels) {
    if (soloCta && label.toLowerCase() !== String(soloCta).toLowerCase()) continue;
    const acc = accounts[label]; if (!acc?.refresh_token) continue;
    let tok;
    try {
      const t = await mlRefresh(ML_CLIENT_ID, ML_CLIENT_SECRET, acc.refresh_token);
      await db.patch('mlapi/tokens/' + label, { refresh_token: t.refresh_token, updated_ts: Date.now() });
      tok = t.access_token;
    } catch { continue; }
    if (!tokUno) tokUno = tok;   // cualquiera sirve para preguntar el nombre de una categoría: es público
    const ids = Object.entries(links).filter(([m, e]) =>
      m.startsWith('MLA') && e && e.cuenta === label && !e.ignored && (e.status || '') !== 'closed').map(([m]) => m);
    for (let k = 0; k < ids.length; k += 20) {
      let arr;
      try { arr = await mlGet('/items?ids=' + ids.slice(k, k + 20).join(',') + '&attributes=id,title,status,price,catalog_listing,category_id,secure_thumbnail,thumbnail,domain_id,user_product_id,tags,health', tok); }
      catch { continue; }
      for (const row of (arr || [])) {
        const b = row.body || {}; const mla = b.id; if (!mla || !links[mla]) continue;
        // LA CATEGORÍA SE ANOTA ANTES DEL FILTRO DE ACTIVAS, a propósito. Abajo se saltean las
        // pausadas porque no pelean ninguna caja, pero una publicación pausada SIGUE teniendo
        // rubro y su producto sigue habiendo vendido: si se anotara después, todo lo pausado
        // quedaría "sin rubro" para siempre y el margen por rubro tendría un agujero mudo.
        if (b.category_id && links[mla].cat !== b.category_id) upd[mla + '/cat'] = b.category_id;
        if (b.category_id) res.cats.add(b.category_id);
        // LA FOTO DE LA PUBLICACIÓN, por el mismo motivo que el código de Full: es para que él
        // MIRE y confirme que está pensando en el producto correcto. Va acá arriba, junto con la
        // categoría, para que también la tengan las pausadas.
        //
        // LA FOTO SE GUARDA SIEMPRE POR https, Y ESO NO ES UN DETALLE: el panel se sirve por
        // https y un navegador BLOQUEA una imagen http adentro de una página https. La foto no se
        // vería y NO habría ningún error a la vista — el fallo mudo de siempre.
        //
        // MEDIDO el 21/09/2026 con `mismoprod`, porque la primera versión guardó 0 de 384:
        //  · ML manda `thumbnail` **por http** en 69 de 69 · `secure_thumbnail` **NO viene** (0/69)
        //  · el MISMO servidor contesta por https: **200 · image/webp** ✅
        // Así que alcanza con cambiarle el http por https, sin una consulta más. No se da por
        // bueno "porque un CDN normalmente sirve las dos": se probó.
        //
        // Sólo se cambia el esquema en los servidores de ML. Una dirección de otro lado se deja
        // como está y, si es http, no se guarda: preferimos no tener foto antes que un hueco.
        //
        // EL DOMINIO SE COMPARA ENTERO, no "que contenga mlstatic". La primera versión usaba
        // `[^/]*mlstatic\.com` sin cerrar el final, y con eso `mlstatic.com.malo.net` pasaba el
        // filtro: alcanzaba con poner el nombre adelante para que el panel cargara una imagen de
        // cualquier servidor. Lo agarró la prueba, no la lectura.
        const _th = String(b.secure_thumbnail || b.thumbnail || '');
        const fotoML = /^https:/i.test(_th) ? _th
          : (/^http:\/\/(?:[^/]*\.)?mlstatic\.com(?:[:/]|$)/i.test(_th) ? _th.replace(/^http:/i, 'https:') : null);
        if (fotoML && links[mla].foto !== fotoML) upd[mla + '/foto'] = fotoML;
        if (fotoML) res.fotos++;
        if (b.domain_id && links[mla].dom !== b.domain_id) upd[mla + '/dom'] = b.domain_id;
        // EL IDENTIFICADOR CON EL QUE ML DICE "ESTAS SON EL MISMO PRODUCTO". Medido el 21/09 con
        // `mismoprod` sobre 384 publicaciones: cuando ML las junta, **nunca contradijo nuestras
        // fichas** (24 grupos de 24). Pero agrupa sólo ADENTRO de una cuenta — la Tira Led está en
        // las cuatro y tiene 4 ids —, igual que el código de Full. Se guarda para el alta de
        // publicaciones nuevas, que es donde hoy se adivina por el título.
        if (b.user_product_id && links[mla].upid !== b.user_product_id) upd[mla + '/upid'] = b.user_product_id;
        // 6.D6 (etapa 6, eligió la a, 21/10/2026): LAS ETIQUETAS DE CALIDAD DE CADA PUBLICACIÓN, TODAS. ML pone en `tags` cosas
        // como `poor_quality_thumbnail`, `incomplete_technical_specs` o `moderation_penalty`, y en `health` un número de 0 a 1
        // (ML no lo da para catálogo: ahí viene vacío). Se guardan crudas (`etq`, texto separado por comas) y la `planilla`
        // lista las que no venden y tienen alguna (`etqProblemas`). Si ML no manda `tags` NO se borra lo guardado: falta de
        // dato no es "sin problemas". Antes del filtro de activas, para que también las tengan las pausadas.
        if (Array.isArray(b.tags)) { const _et = b.tags.map(String).filter(Boolean).sort().join(','); if (links[mla].etq !== _et) upd[mla + '/etq'] = _et || ''; }
        if (b.health != null && Number.isFinite(Number(b.health))) { const _h = Math.round(Number(b.health) * 100) / 100; if (links[mla].salud !== _h) upd[mla + '/salud'] = _h; }
        if (b.status !== 'active') continue;      // pausada o cerrada: no está peleando ninguna caja
        res.mirados++;
        const stamp = (st, ptw) => {
          upd[mla + '/caja'] = st;
          upd[mla + '/cajaPtw'] = ptw || null;
          upd[mla + '/cajaTs'] = Date.now();
          res[st]++;
        };
        if (!b.catalog_listing) { stamp('nocat', null); if (_sugPend.length < SUG_MAX_VUELTA && !(Number(links[mla].sugTs) > Date.now() - SUG_CADA_H * 3600e3)) _sugPend.push({ mla, tok }); continue; }
        let ptw = null;
        try { ptw = await mlGet('/items/' + mla + '/price_to_win?version=v2', tok); } catch { /* se deja lo de antes */ }
        if (!ptw || !ptw.status) continue;
        const st = ptw.status === 'winning' ? 'winning'
          : ptw.status === 'sharing_first_place' ? 'sharing'
            : (ptw.status === 'competing' || ptw.status === 'losing') ? 'losing' : 'sincaja';
        const pw = (st !== 'winning' && Number(ptw.price_to_win) > 0) ? Math.round(Number(ptw.price_to_win)) : null;
        stamp(st, pw);
        // Idea 4 de la etapa 6 (27/09/2026, "hacela"): cuánta gente te ve de la ficha (ML lo dice
        // en palabras: maximum / medium / minimum) y con cuántos compartís el 1er puesto. Medido
        // con `valefull` el 22/09: 12 de 12 traen visit_share, 11 de 12 los competidores. Lo que
        // no viene como se espera se guarda vacío, nunca adivinado.
        const _vs = String(ptw.visit_share || '').toLowerCase();
        upd[mla + '/cajaVis'] = ['maximum', 'medium', 'minimum'].includes(_vs) ? _vs : null;
        const _cs = ptw.competitors_sharing_first_place;
        upd[mla + '/cajaComp'] = Array.isArray(_cs) ? _cs.length : (Number.isFinite(Number(_cs)) && _cs !== null && _cs !== '' ? Number(_cs) : null);
        // 6.D2 (etapa 6, eligió la a): POR QUÉ SE PIERDE LA CAJA, sin una consulta más (viene en el mismo price_to_win). `boosts`
        // dice qué te da ventaja y qué te falta (medido con `valefull` el 22/09: `fulfillment:boosted` y `free_installments:
        // opportunity` en 12 de 12) y `winner.price` a cuánto está el que gana. Se guarda compacto (`cajaBoost`, texto
        // "id:estado|id:estado") y el precio del que gana (`cajaGanP`). `cajaPorCuotas` = la perdés (o compartís), al que gana NO
        // le ganás por precio (está a tu precio o más caro) y ML dice que te faltan cuotas sin interés: el remedio es la gemela
        // Premium (misma plata neta), no bajar. Lo que no viene se guarda vacío, nunca adivinado.
        const _bo = Array.isArray(ptw.boosts) ? ptw.boosts.filter((x) => x && x.id).map((x) => String(x.id) + ':' + String(x.status || '?')) : null;
        upd[mla + '/cajaBoost'] = _bo ? _bo.join('|') : null;
        const _wp = Number(ptw.winner && ptw.winner.price) || 0;
        upd[mla + '/cajaGanP'] = st !== 'winning' && _wp > 0 ? Math.round(_wp) : null;
        upd[mla + '/cajaPorCuotas'] = cajaPerdidaPorCuotas(st, Number(b.price) || 0, _wp, _bo) || null;
        // 6.D5 (etapa 6, eligió la a): ¿EL QUE GANA ESTÁ EN PROMO? Si ML manda el precio tachado del ganador (`original_price`
        // o `regular_amount`) se guarda cuánto está rebajado (%); si no lo manda queda vacío (no se sabe, no es "no está en
        // promo"). NO MEDIDO TODAVÍA: correr `ptwganador` para ver qué campos trae `winner`.
        const _wo = Number(ptw.winner && (ptw.winner.original_price || ptw.winner.regular_amount)) || 0;
        upd[mla + '/cajaGanPromo'] = st !== 'winning' && _wp > 0 && _wo > _wp * 1.01 ? Math.round((1 - _wp / _wo) * 100) : null;
        res.porCuotas += upd[mla + '/cajaPorCuotas'] ? 1 : 0;
        res.filas.push({ mla, label, nom: String(b.title || '').slice(0, 46), st, precio: Math.round(b.price || 0), ptw: pw });
      }
    }
  }
  // ── 6.D4 · EL PRECIO QUE SUGIERE ML PARA LAS QUE NO SON DE CATÁLOGO (etapa 6, eligió la a, 21/10/2026) ──────────
  // Sin catálogo no hay competidor legible (ML da 403 en publicaciones ajenas), y para el salto de techo y el precio de
  // lanzamiento no había ninguna referencia de afuera. `/suggestions/items/<MLA>/details` trae lo que ML sugiere y la más
  // barata parecida. Se guarda en la publicación (`sugP`, `sugMin`, `sugTs`) y la planilla lo muestra como DATO para mi
  // decisión: NO mueve ningún precio solo. Una vez por día por publicación (SUG_CADA_H) y con tope por vuelta. Si ML no
  // contesta o no trae el número, se anota la fecha y nada más (no se inventa una sugerencia). Forma de la respuesta NO
  // medida todavía: se aceptan `suggested_price.amount` o `suggested_price` suelto; correr `sugerido:<MLA>` para mirarla.
  for (const x of _sugPend) {
    let sg = null; try { sg = await mlGet(`/suggestions/items/${x.mla}/details`, x.tok); } catch { sg = null; }
    const r = leerSugerenciaML(sg);
    upd[x.mla + '/sugTs'] = Date.now();
    if (r.sug) { upd[x.mla + '/sugP'] = r.sug; upd[x.mla + '/sugMin'] = r.min || null; res.sug++; } else res.sugSin++;   // sin número: queda lo de antes
  }
  // ── EL NOMBRE DEL RUBRO ────────────────────────────────────────────────────────────────────
  // `MLA352679` no le dice nada a nadie: lo que hace falta es la RAÍZ del árbol ("Belleza y
  // Cuidado Personal"), que es la granularidad de un margen por rubro. Sale de `path_from_root[0]`
  // de `/categories/<id>` (medido el 21/09/2026 con `reputa`).
  //
  // El nombre se pide UNA sola vez por categoría, no por publicación: la categoría no depende de
  // cuál publicación sea, y sin esta caché las ~140 publicaciones preguntarían lo mismo decenas de
  // veces — el error de velocidad que ya mordió en la primera versión de `avisos`.
  const yaNom = {};
  for (const e of Object.values(links)) if (e && e.cat && e.catNom) yaNom[e.cat] = e.catNom;
  const faltan = tokUno ? [...res.cats].filter((c) => !yaNom[c]) : [];
  // TOPE POR VUELTA, y NO es mudo: esto corre dentro de la vuelta horaria y un día con muchas
  // categorías nuevas no puede colgar el resto del paso. Las que quedan salen en la vuelta
  // siguiente y se dicen acá, que es la lección del tope de `calcCajaBarata`.
  const MAX_CATS = 30;
  for (const c of faltan.slice(0, MAX_CATS)) {
    let nom = null;
    try {
      const d = await mlGet('/categories/' + c, tokUno);
      nom = ((d.path_from_root || [])[0] || {}).name || null;
    } catch { /* si ML no contesta se deja sin nombre: la vuelta siguiente lo reintenta */ }
    if (!nom) continue;
    yaNom[c] = nom;
    res.catsNuevas++;
  }
  res.catsFaltan = Math.max(0, faltan.length - MAX_CATS);
  // El nombre se guarda en CADA publicación y no en una tabla aparte, para que la pantalla lo lea
  // de una sin un segundo salto — es el mismo criterio con el que ya se guarda el código de Full.
  for (const [mla, e] of Object.entries(links)) {
    const cat = (upd[mla + '/cat'] || e.cat);
    if (!cat || !yaNom[cat]) continue;
    if (e.catNom !== yaNom[cat]) upd[mla + '/catNom'] = yaNom[cat];
  }
  if (!DRY && Object.keys(upd).length) await db.patch('cyc/mllinks', upd);
  return res;
}

// ── LA REPUTACIÓN DE CADA CUENTA (21/09/2026) ──────────────────────────────────────────────────
// Pedido suyo mirando Lumelí: "agregá el margen por categoría y la reputación de todas las cuentas".
//
// OJO CON LA DIRECCIÓN: `/users/<id>/seller_reputation` **no existe** — devuelve una página web, no
// un 404, así que leerlo como "no anda ML" sería el error de siempre. La reputación viene ADENTRO
// de `/users/<id>`. Medido el 21/09 con `apisnuevas` y confirmado con `reputa`.
//
// Va en la vuelta HORARIA y no en las de 2 minutos: la reputación se mueve por trimestre, no por
// minuto, y son 4 llamadas más por vuelta.
