              await espera(250); const ph = await mlGetR(`/products/${H}`); if (!ph || !ph.id) continue; ph._leido = 1;
              // El hijo (un color) casi nunca repite el código de modelo ni todas las medidas del padre, que ya pasó el chequeo:
