    if (!x.e.f) { console.log('     (sin foto de Paraguay: no pasa a Para probar)'); continue; }
    { const _ns = pyCatNoSeMira(x.e.n); if (_ns) { console.log(`     (${_ns}: categoría que no se mira, no pasa a Para probar)`); continue; } }
