    if (_reb && String(x.upd.mi).toUpperCase() in ((_reb[1].mlNoEs) || {})) { console.log('     (es el mismo catálogo que ya se rechazó: no vuelve)'); continue; }
    const id = _reb ? _reb[0] : 'c' + Date.now() + 'p' + i;
