      const re = (await db.get('mlapi/listas/' + k)) || {}; let ok = 0; for (const x of ks) { const c = x.slice(0, x.lastIndexOf('/')), f = x.slice(x.lastIndexOf('/') + 1); const v = (re[c] || {})[f]; if (f === 'noWeb' ? !!v === !!upd[x] : v === upd[x]) ok++; }
