      for (const { r } of listas) console.log(r.linea ? `${r.tipo === 'entrarpromo' ? 'entrarpromo' : 'decido'}:${r.linea};go` : `(${r.mla}: no guardó el renglón: rearmarlo con ${money(r.precio)} y ${(r.banderas || []).map((b) => (b === 'remate' ? '#remate' : '!' + b)).join('')})`);
