      console.log(`\n  releído del panel: producto ${ver.prodId || '(ninguno)'} ${okP ? '✓' : '✗'} · oculta ${ver.ignored ? 'SÍ ✗' : 'no ✓'} · "no la vendemos más" ${ver.noVendemosMas ? 'SÍ ✗' : 'no ✓'}`);
