          ban: ['piso', 'bajocero', 'sintecho', 'golpe', 'sincerteza', 'bajopiso', 'nosobra', 'sinlinea', 'nobajar'].filter((k) => q[k]), aut: autE, mg: mg ?? null, mgP: mgP ?? null,
