        if (c.estado !== 'llegado' || !c.ofiAlLlegar || !(Number(c.llegoTs) > 0) || hoy - Number(c.llegoTs) > 7 * 864e5) continue;
        const uP = {}; for (const it of (c.items || [])) if (it && it.prodId) uP[it.prodId] = (uP[it.prodId] || 0) + (parseInt(it.u) || 0);
