        const cm = (cam[p.id] || {}).tot || 0, py = viaPy[p.id] || 0, pvv = Object.values(viaPv[p.id] || {}).reduce((a, b) => a + b, 0), liv = (viaLi[p.id] || {}).tot || 0;
        const cost = Math.round((Number(p.costFullUSD) || Number(p.costUSD) || 0) * tc);
