        const hP = histD(s);
        const esBsasP = p.origen !== 'py' && !(/paulvic/i.test(provN[p.proveedorId] || '') || /paulvic/i.test(p.name || ''));   // el mismo grupo que BSAS de abajo
        const m60 = med(pU[p.id]);
        const uv = ultV(p.id);
