                    for (let i = 0; i < 12 && Pn <= 650000; i++) { const mm = await mgEn(Pn); if (mm == null) { falla = Pn; break; } if (mm >= PISO) { ok = { P: Pn, mg: mm }; break; } Pn = rnd(Pn + (Pn < 10000 ? 100 : 1000)); }
